_INDO_BACKUP_STOP = threading.Event()
_INDO_BACKUP_THREAD = None
_INDO_BACKUP_CLIENT = None
_INDO_BACKUP_LAST_MANIFEST = None
_INDO_BACKUP_LAST_MANIFEST_KEY = (INDO_BACKUP_PREFIX + "/latest.json") if INDO_BACKUP_PREFIX else "latest.json"


def _indo_backup_require_config():
    if not INDO_BACKUP_BUCKET:
        raise RuntimeError("INDO_BACKUP_ENABLED=1 requires INDO_BACKUP_BUCKET.")
    if not INDO_BACKUP_PREFIX:
        raise RuntimeError("INDO_BACKUP_PREFIX cannot be empty.")


def _indo_backup_client():
    global _INDO_BACKUP_CLIENT
    if _INDO_BACKUP_CLIENT is not None:
        return _INDO_BACKUP_CLIENT
    _indo_backup_require_config()
    try:
        import boto3
        from botocore.config import Config
    except ImportError as exc:
        raise RuntimeError("Cloud backup is enabled but boto3 is missing. Add boto3>=1.35 to requirements.txt.") from exc
    options = {
        "service_name": "s3",
        "region_name": INDO_BACKUP_REGION,
        "endpoint_url": INDO_BACKUP_ENDPOINT_URL,
        "config": Config(
            signature_version="s3v4",
            connect_timeout=8,
            read_timeout=45,
            retries={"max_attempts": 3, "mode": "standard"},
        ),
    }
    if INDO_BACKUP_ACCESS_KEY_ID:
        options["aws_access_key_id"] = INDO_BACKUP_ACCESS_KEY_ID
    if INDO_BACKUP_SECRET_ACCESS_KEY:
        options["aws_secret_access_key"] = INDO_BACKUP_SECRET_ACCESS_KEY
    _INDO_BACKUP_CLIENT = boto3.client(**options)
    return _INDO_BACKUP_CLIENT


def _indo_backup_safe_relative(relative: str) -> str | None:
    from pathlib import PurePosixPath
    raw = str(relative or "").replace("\\", "/")
    path = PurePosixPath(raw)
    if not raw or path.is_absolute() or any(part in ("", ".", "..") for part in path.parts):
        return None
    if path.name == "session_secret.key" or path.name == ".indo_write_test":
        return None
    if any(part in {".git", "__pycache__", ".pytest_cache", ".venv", "venv", "node_modules"} for part in path.parts):
        return None
    if path.name.endswith((".tmp", ".temp", ".pyc", ".log", ".lock", "-wal", "-shm", "-journal")):
        return None
    return path.as_posix()


def _indo_backup_iter_files():
    root = INDO_DATA_DIR.resolve()
    for current, dirs, files in os.walk(root):
        dirs[:] = sorted(d for d in dirs if d not in {".git", "__pycache__", ".pytest_cache", ".venv", "venv", "node_modules"})
        for filename in sorted(files):
            path = Path(current) / filename
            try:
                if path.is_symlink() or not path.is_file():
                    continue
                relative = path.relative_to(root).as_posix()
                safe = _indo_backup_safe_relative(relative)
                if safe:
                    yield safe, path
            except (OSError, ValueError):
                continue


def _indo_backup_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _indo_backup_make_consistent_copy(source: Path, destination: Path, relative: str):
    """Use SQLite's online backup API for DB files; copy other files with change checks."""
    destination.parent.mkdir(parents=True, exist_ok=True)
    if source.suffix.lower() in {".db", ".sqlite", ".sqlite3"}:
        src_conn = None
        dst_conn = None
        try:
            src_uri = "file:" + urllib.parse.quote(str(source.resolve())) + "?mode=ro"
            src_conn = sqlite3.connect(src_uri, uri=True, timeout=30)
            dst_conn = sqlite3.connect(str(destination), timeout=30)
            src_conn.backup(dst_conn, pages=256, sleep=0.05)
            dst_conn.commit()
        finally:
            if dst_conn is not None:
                dst_conn.close()
            if src_conn is not None:
                src_conn.close()
        return

    last_error = None
    for _attempt in range(3):
        try:
            before = source.stat()
            shutil.copyfile(source, destination)
            after = source.stat()
            copied = destination.stat()
            if before.st_size == after.st_size == copied.st_size and before.st_mtime_ns == after.st_mtime_ns:
                return
            last_error = RuntimeError("file changed during backup")
        except OSError as exc:
            last_error = exc
        try:
            destination.unlink(missing_ok=True)
        except OSError:
            pass
        time.sleep(0.15)
    raise RuntimeError(f"Could not capture a stable backup copy of {relative}: {type(last_error).__name__}")


def _indo_backup_read_latest_manifest(client):
    try:
        response = client.get_object(Bucket=INDO_BACKUP_BUCKET, Key=_INDO_BACKUP_LAST_MANIFEST_KEY)
        raw = response["Body"].read(8 * 1024 * 1024 + 1)
        if len(raw) > 8 * 1024 * 1024:
            raise RuntimeError("Indo cloud backup manifest is unexpectedly large.")
        manifest = json.loads(raw.decode("utf-8"))
        if not isinstance(manifest, dict) or manifest.get("schema") != 1 or not isinstance(manifest.get("files"), list):
            raise RuntimeError("Indo cloud backup manifest has an unsupported format.")
        return manifest
    except Exception as exc:
        response = getattr(exc, "response", {}) or {}
        error = response.get("Error", {}) if isinstance(response, dict) else {}
        code = str(error.get("Code", ""))
        status = response.get("ResponseMetadata", {}).get("HTTPStatusCode") if isinstance(response, dict) else None
        if code in {"NoSuchKey", "404", "NotFound"} or status == 404:
            return None
        # botocore's NoSuchKey may be surfaced with a provider-specific exception.
        if type(exc).__name__ in {"NoSuchKey", "NotFound"}:
            return None
        raise


def _indo_backup_restore_latest():
    """Restore only missing local files; never overwrite an existing local user file."""
    global _INDO_BACKUP_LAST_MANIFEST
    if not INDO_BACKUP_ENABLED or not INDO_BACKUP_RESTORE_ON_START:
        return False
    client = _indo_backup_client()
    manifest = _indo_backup_read_latest_manifest(client)
    if manifest is None:
        print("[Indo cloud backup] No prior snapshot found; this instance will create the first backup.")
        _INDO_BACKUP_LAST_MANIFEST = None
        return False
    restored = 0
    for item in manifest["files"]:
        if not isinstance(item, dict):
            raise RuntimeError("Indo cloud backup manifest contains an invalid file entry.")
        relative = _indo_backup_safe_relative(item.get("path", ""))
        key = str(item.get("key") or "")
        expected_hash = str(item.get("sha256") or "")
        if not relative or not key.startswith(INDO_BACKUP_PREFIX + "/snapshots/") or not re.fullmatch(r"[a-f0-9]{64}", expected_hash):
            raise RuntimeError("Indo cloud backup manifest failed path or integrity validation.")
        target = INDO_DATA_DIR / Path(*relative.split("/"))
        if target.exists() and target.is_file() and target.stat().st_size > 0:
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        temp_target = target.with_name(target.name + ".restore.tmp")
        try:
            client.download_file(INDO_BACKUP_BUCKET, key, str(temp_target))
            if _indo_backup_sha256(temp_target) != expected_hash:
                raise RuntimeError(f"Checksum mismatch while restoring {relative}.")
            os.replace(temp_target, target)
            restored += 1
        finally:
            try:
                temp_target.unlink(missing_ok=True)
            except OSError:
                pass
    _INDO_BACKUP_LAST_MANIFEST = manifest
    print(f"[Indo cloud backup] Restore check complete; restored {restored} missing files from snapshot {manifest.get('snapshot_id', 'unknown')}.")
    return restored > 0


def _indo_backup_create_snapshot():
    """Create an immutable incremental snapshot and atomically advance latest.json."""
    global _INDO_BACKUP_LAST_MANIFEST
    if not INDO_BACKUP_ENABLED:
        return False
    if not _INDO_BACKUP_LOCK.acquire(blocking=False):
        return False
    temp_root = None
    try:
        client = _indo_backup_client()
        previous = _INDO_BACKUP_LAST_MANIFEST
        if previous is None:
            previous = _indo_backup_read_latest_manifest(client)
        previous_files = {str(x.get("path")): x for x in (previous or {}).get("files", []) if isinstance(x, dict)}
        snapshot_id = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime()) + "-" + uuid.uuid4().hex[:10]
        snapshot_prefix = f"{INDO_BACKUP_PREFIX}/snapshots/{snapshot_id}/"
        temp_root = Path(tempfile.mkdtemp(prefix="indo-backup-"))
        new_files = []
        changed_count = 0
        for relative, source in _indo_backup_iter_files():
            staged = temp_root / Path(*relative.split("/"))
            _indo_backup_make_consistent_copy(source, staged, relative)
            digest = _indo_backup_sha256(staged)
            size = staged.stat().st_size
            old = previous_files.get(relative)
            if old and old.get("sha256") == digest and int(old.get("size", -1)) == size and str(old.get("key", "")).startswith(INDO_BACKUP_PREFIX + "/snapshots/"):
                object_key = old["key"]
            else:
                object_key = snapshot_prefix + relative
                client.upload_file(str(staged), INDO_BACKUP_BUCKET, object_key)
                changed_count += 1
            new_files.append({"path": relative, "key": object_key, "size": size, "sha256": digest})
        manifest = {
            "schema": 1,
            "app": "Indo AI",
            "snapshot_id": snapshot_id,
            "created_at": int(time.time()),
            "data_directory": "INDO_DATA_DIR",
            "files": new_files,
        }
        encoded = json.dumps(manifest, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        client.put_object(Bucket=INDO_BACKUP_BUCKET, Key=_INDO_BACKUP_LAST_MANIFEST_KEY,
                          Body=encoded, ContentType="application/json", CacheControl="no-store")
        _INDO_BACKUP_LAST_MANIFEST = manifest
        print(f"[Indo cloud backup] Snapshot {snapshot_id} committed: {len(new_files)} files, {changed_count} changed uploads.")
        return True
    finally:
        if temp_root is not None:
            shutil.rmtree(temp_root, ignore_errors=True)
        _INDO_BACKUP_LOCK.release()


def _indo_backup_mark_dirty():
    if INDO_BACKUP_ENABLED:
        _INDO_BACKUP_DIRTY.set()


def _indo_backup_worker():
    last_backup = 0.0
    while not _INDO_BACKUP_STOP.wait(10):
        now = time.monotonic()
        due_to_change = _INDO_BACKUP_DIRTY.is_set() and now - last_backup >= 20
        due_to_interval = now - last_backup >= INDO_BACKUP_INTERVAL_SECONDS
        if not (due_to_change or due_to_interval):
            continue
        _INDO_BACKUP_DIRTY.clear()
        try:
            _indo_backup_create_snapshot()
        except Exception as exc:
            print(f"[Indo cloud backup] Snapshot failed; the previous committed snapshot remains intact ({type(exc).__name__}: {exc}).")
        last_backup = time.monotonic()


# Restore before app-specific SQLite stores and user directories are initialized.
# If cloud backup is enabled but inaccessible/corrupt, fail startup rather than
# silently serving an empty account database and later replacing the good backup.
if INDO_BACKUP_ENABLED:
    try:
        _indo_backup_require_config()
        _indo_backup_restore_latest()
    except Exception as _backup_restore_error:
        raise RuntimeError(
            "Indo AI cloud restore failed. Startup stopped to protect existing cloud data. "
            "Check the INDO_BACKUP_* Render environment variables and bucket access."
        ) from _backup_restore_error

UPLOAD_DIR = Path(os.getenv("INDO_UPLOAD_DIR", str(INDO_DATA_DIR / "indo_uploads"))).expanduser()
UPLOAD_DIR.mkdir(parents=True, exist_ok=True)

# Local reusable answer dataset. It stores successful Q&A pairs; it does NOT train Gemini.
DATASET_ENABLED = os.getenv("INDO_DATASET_ENABLED", "1").strip().lower() not in ("0", "false", "no", "off")
DATASET_PATH = Path(os.getenv("INDO_DATASET_PATH", str(INDO_DATA_DIR / "IndoMemory.db"))).expanduser()
_DATASET_LOCK = threading.RLock()


# ============================================================
# FASTAPI
# ============================================================

app = FastAPI(
    title=APP_NAME,
    version=APP_VERSION
)

app.mount(
    "/uploads",
    StaticFiles(directory=str(UPLOAD_DIR)),
    name="uploads"
)

# GARUDA security boundary. This middleware is independent of the AI agents.
GARUDA = GarudaSecurity(INDO_DATA_DIR)
# New, separate, opt-in knowledge DB. Existing account/chat/memory databases are untouched.
VISHNU_KNOWLEDGE_STORE = VersionedKnowledgeStore(INDO_DATA_DIR / "vishnu_knowledge.sqlite3")

@app.middleware("http")
async def garuda_security_middleware(request: Request, call_next):
    path = request.url.path
    if path.startswith(("/api/", "/auth/")):
        remote_ip = request.client.host if request.client else "unknown"
        client_ip = GARUDA.resolve_client_ip(remote_ip, request.headers)
        try:
            content_length = int(request.headers.get("content-length", "0") or 0)
        except (TypeError, ValueError):
            content_length = 0
        decision = GARUDA.inspect(request.method, path, client_ip, request.headers, content_length)
        if not decision.get("allowed"):
            headers = {"Cache-Control": "no-store"}
            if decision.get("retry_after"):
                headers["Retry-After"] = str(decision["retry_after"])
            return JSONResponse({"ok": False, "error": decision.get("reason", "Request rejected by GARUDA."),
                                 "security_layer": "GARUDA"}, status_code=int(decision.get("status_code", 403)), headers=headers)
    response = await call_next(request)
    if response.status_code < 400 and request.method in {"POST", "PUT", "PATCH", "DELETE"}:
        _indo_backup_mark_dirty()
    forwarded_proto = str(request.headers.get("x-forwarded-proto", "")).split(",", 1)[0].strip().lower()
    is_https = request.url.scheme == "https" or forwarded_proto == "https" or bool(os.getenv("RENDER"))
    for header, value in GARUDA.security_headers(is_https).items():
        response.headers.setdefault(header, value)
    return response


# Multi-device streaming capacity. Starlette runs synchronous streaming iterators
# through AnyIO's worker-thread limiter (often only 40 threads by default). Raising
# this limit lets more independent chat streams make progress concurrently; it does
# not bypass model-provider quotas or replace horizontal scaling for large traffic.
INDO_STREAM_THREAD_LIMIT = max(40, min(int(os.getenv("INDO_STREAM_THREAD_LIMIT", "200")), 1000))

@app.on_event("startup")
async def _indo_configure_stream_concurrency():
    try:
        import anyio.to_thread
        limiter = anyio.to_thread.current_default_thread_limiter()
        limiter.total_tokens = max(limiter.total_tokens, INDO_STREAM_THREAD_LIMIT)
        print(f"[Indo capacity] concurrent stream worker limit configured: {limiter.total_tokens}")
    except Exception as exc:
        # Keep startup reliable on environments with an older AnyIO implementation.
        print(f"[Indo capacity] using default stream worker limit ({type(exc).__name__})")


@app.on_event("startup")
async def _indo_start_cloud_backup_worker():
    global _INDO_BACKUP_THREAD
    if not INDO_BACKUP_ENABLED:
        print("[Indo cloud backup] Disabled. Configure a private S3-compatible bucket to enable long-term backups.")
        return
    _INDO_BACKUP_STOP.clear()
    _INDO_BACKUP_THREAD = threading.Thread(target=_indo_backup_worker, name="indo-cloud-backup", daemon=True)
    _INDO_BACKUP_THREAD.start()
    _INDO_BACKUP_DIRTY.set()  # create/refresh a baseline snapshot shortly after startup
    print(f"[Indo cloud backup] Enabled; interval={INDO_BACKUP_INTERVAL_SECONDS}s; bucket configured; prefix={INDO_BACKUP_PREFIX}.")


@app.on_event("shutdown")
async def _indo_final_cloud_backup():
    if not INDO_BACKUP_ENABLED:
        return
    _INDO_BACKUP_STOP.set()
    try:
        await asyncio.to_thread(_indo_backup_create_snapshot)
    except Exception as exc:
        print(f"[Indo cloud backup] Final shutdown snapshot failed ({type(exc).__name__}). The last committed snapshot is preserved.")


# ============================================================
# GOOGLE ACCOUNT SESSIONS (used to isolate each user's music)
# Configure GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET and optionally
# GOOGLE_REDIRECT_URI in the environment before using Google sign-in.
# ============================================================
GOOGLE_CLIENT_ID = os.getenv("GOOGLE_CLIENT_ID", "").strip()
GOOGLE_CLIENT_SECRET = os.getenv("GOOGLE_CLIENT_SECRET", "").strip()
# Leave blank when not explicitly configured so OAuth can derive the public callback
# URL from the incoming request (important behind Render/reverse proxies). In production,
# setting GOOGLE_REDIRECT_URI explicitly is still recommended and must match Google Cloud.
GOOGLE_REDIRECT_URI = os.getenv("GOOGLE_REDIRECT_URI", "").strip()


def _indo_google_callback_uri(request: Request) -> str:
    """Resolve the exact OAuth callback URI, respecting common reverse-proxy headers."""
    if GOOGLE_REDIRECT_URI:
        return GOOGLE_REDIRECT_URI
    forwarded_proto = str(request.headers.get("x-forwarded-proto", "")).split(",", 1)[0].strip()
    forwarded_host = str(request.headers.get("x-forwarded-host", "")).split(",", 1)[0].strip()
    host = forwarded_host or str(request.headers.get("host", "")).strip()
    if not host:
        host = request.url.netloc
    scheme = forwarded_proto or request.url.scheme
    if host.lower().startswith(("localhost", "127.0.0.1")) and not forwarded_proto:
        scheme = "http"
    elif not forwarded_proto and os.getenv("RENDER"):
        scheme = "https"
    if scheme not in ("http", "https"):
        scheme = "https" if os.getenv("RENDER") else "http"
    return f"{scheme}://{host}/auth/google/callback"
INDO_AUTH_DIR = Path(os.getenv("INDO_AUTH_DIR", str(INDO_DATA_DIR / "IndoAuthData"))).expanduser()
INDO_AUTH_DIR.mkdir(parents=True, exist_ok=True)
# Session signing must remain stable across Render restarts/redeploys and across
# workers. Render's local filesystem may be ephemeral, so a file-generated key alone
# is not a reliable production source. Prefer a dedicated INDO_SESSION_SECRET; if it
# is not configured, derive a domain-separated key from the stable Google OAuth
# client secret so all instances still validate the same session cookies.
_secret_env = os.getenv("INDO_SESSION_SECRET", "").strip()
_secret_file = INDO_AUTH_DIR / "session_secret.key"
if len(_secret_env.encode("utf-8")) >= 32:
    _SESSION_SECRET = _secret_env.encode("utf-8")
elif GOOGLE_CLIENT_SECRET:
    _SESSION_SECRET = hmac.new(
        GOOGLE_CLIENT_SECRET.encode("utf-8"),
        b"IndoAI/session-signing-key/v1",
        hashlib.sha256,
    ).digest()
else:
    # Local-development fallback only. On hosted production, configure
    # INDO_SESSION_SECRET in the hosting dashboard for reliable persistence.
    try:
        _SESSION_SECRET = _secret_file.read_bytes()
        if len(_SESSION_SECRET) < 32:
            raise ValueError("Session secret too short")
    except Exception:
        _SESSION_SECRET = secrets.token_bytes(48)
        _secret_file.write_bytes(_SESSION_SECRET)
        try:
            os.chmod(_secret_file, 0o600)
        except OSError:
            pass
    if os.getenv("RENDER") and not GOOGLE_CLIENT_SECRET:
        print("[Indo persistence warning] Set a stable INDO_SESSION_SECRET (at least 32 characters) in Render. Otherwise sign-in cookies can become invalid if the local secret file is lost during a redeploy.")

try:
    INDO_SESSION_DAYS = max(7, min(180, int(os.getenv("INDO_SESSION_DAYS", "90"))))
except (TypeError, ValueError):
    INDO_SESSION_DAYS = 90
INDO_SESSION_SECONDS = INDO_SESSION_DAYS * 24 * 60 * 60
INDO_MUSIC_USERS_DIR = Path(os.getenv("INDO_MUSIC_USERS_DIR", str(INDO_DATA_DIR / "IndoMusicUsers"))).expanduser()
INDO_MUSIC_USERS_DIR.mkdir(parents=True, exist_ok=True)
# Profile photos are stored server-side per canonical account identity. On Render,
# mount a persistent disk at /var/data and set INDO_DATA_DIR=/var/data so these files
# survive deploys/restarts. INDO_PROFILE_DIR can override the profile-photo directory.
INDO_PROFILE_DIR = Path(os.getenv("INDO_PROFILE_DIR", str(INDO_DATA_DIR / "IndoProfiles"))).expanduser()
INDO_PROFILE_DIR.mkdir(parents=True, exist_ok=True)
INDO_SESSION_COOKIE = "indo_account_session"
INDO_OAUTH_STATE_COOKIE = "indo_google_oauth_state"

def _indo_b64(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("ascii").rstrip("=")

def _indo_session_signature(payload: str) -> str:
    return _indo_b64(hmac.new(_SESSION_SECRET, payload.encode("ascii"), hashlib.sha256).digest())

def _indo_make_session(email: str, name: str = "", provider: str = "google", user_key: str = "") -> str:
    identity = str(email or "").strip().lower()
    data = {"email": identity, "name": str(name or "")[:120],
            "provider": str(provider or "google")[:24],
            "user_key": str(user_key or (str(provider or "google") + ":" + identity))[:300],
            "exp": int(time.time()) + INDO_SESSION_SECONDS}
    payload = _indo_b64(json.dumps(data, separators=(",", ":")).encode("utf-8"))
    return payload + "." + _indo_session_signature(payload)

def _indo_current_user(request) -> dict | None:
    token = request.cookies.get(INDO_SESSION_COOKIE, "")
    try:
        payload, signature = token.split(".", 1)
        if not hmac.compare_digest(signature, _indo_session_signature(payload)):
            return None
        data = json.loads(base64.urlsafe_b64decode(payload + "=" * (-len(payload) % 4)))
        if int(data.get("exp", 0)) < int(time.time()) or not data.get("email"):
            return None
        return data
    except Exception:
        return None

def _indo_music_user_dir(request) -> Path | None:
    user = _indo_current_user(request)
    if not user:
        return None
    # Separate Google identities from native Indo accounts, even if their labels overlap.
    identity = str(user.get("user_key") or ("google:" + user["email"].lower())).lower()
    user_key = hashlib.sha256(identity.encode("utf-8")).hexdigest()[:32]
    folder = INDO_MUSIC_USERS_DIR / user_key
    folder.mkdir(parents=True, exist_ok=True)
    return folder

def _indo_auth_required_response():
    return JSONResponse({"error": "Sign in with Google or the Indo account linked to your Google identity to access your private music library.", "sign_in_required": True}, status_code=401)

# Native Indo accounts are stored locally. Passwords are salted PBKDF2 hashes;
# plaintext passwords are never written to disk.
INDO_ACCOUNTS_DB = INDO_AUTH_DIR / "accounts.sqlite3"
_INDO_PASSWORD_ROUNDS = 260_000

def _indo_accounts_db():
    conn = sqlite3.connect(str(INDO_ACCOUNTS_DB), timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("""CREATE TABLE IF NOT EXISTS accounts (
        username_norm TEXT PRIMARY KEY,
        username TEXT NOT NULL,
        password_salt TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        created_at INTEGER NOT NULL,
        linked_google_key TEXT,
        linked_google_email TEXT
    )""")
    existing = {row[1] for row in conn.execute("PRAGMA table_info(accounts)").fetchall()}
    if "linked_google_key" not in existing:
        conn.execute("ALTER TABLE accounts ADD COLUMN linked_google_key TEXT")
    if "linked_google_email" not in existing:
        conn.execute("ALTER TABLE accounts ADD COLUMN linked_google_email TEXT")
    conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_indo_accounts_google_key ON accounts(linked_google_key) WHERE linked_google_key IS NOT NULL")
    conn.commit()
    return conn

def _indo_password_hash(password: str, salt: bytes) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, _INDO_PASSWORD_ROUNDS, dklen=32)

def _indo_set_login_cookie(response, token: str):
    response.set_cookie(INDO_SESSION_COOKIE, token, httponly=True, samesite="lax",
        secure=(GOOGLE_REDIRECT_URI.lower().startswith("https://") or bool(os.getenv("RENDER"))),
        max_age=INDO_SESSION_SECONDS, path="/")

def _indo_profile_file_for_user(user: dict) -> Path:
    identity = str(user.get("user_key") or (str(user.get("provider") or "indo") + ":" + str(user.get("email") or "").lower())).lower()
    account_id = hashlib.sha256(identity.encode("utf-8")).hexdigest()[:32]
    return INDO_PROFILE_DIR / (account_id + ".avatar")

def _indo_sync_google_profile(user: dict, profile: dict) -> None:
    """Persist minimal Google profile metadata and cache the verified Google avatar."""
    if not user or user.get("provider") != "google":
        return
    avatar_path = _indo_profile_file_for_user(user)
    profile_path = avatar_path.with_name(avatar_path.stem + ".profile.json")
    safe_profile = {
        "provider": "google",
        "subject_hash": hashlib.sha256(str(user.get("user_key") or "").encode("utf-8")).hexdigest(),
        "email": str(profile.get("email") or user.get("email") or "")[:254].lower(),
        "name": str(profile.get("name") or user.get("name") or "")[:120],
        "given_name": str(profile.get("given_name") or "")[:80],
        "family_name": str(profile.get("family_name") or "")[:80],
        "updated_at": int(time.time()),
    }
    try:
        profile_path.write_text(json.dumps(safe_profile, ensure_ascii=False), encoding="utf-8")
        try: os.chmod(profile_path, 0o600)
        except OSError: pass
    except OSError as exc:
        print("[Indo profile metadata save failed]", type(exc).__name__)

    # Keep a user-uploaded avatar intact; refresh only missing or Google-sourced photos.
    try:
        existing_meta_path = avatar_path.with_suffix(".json")
        existing_meta = json.loads(existing_meta_path.read_text(encoding="utf-8")) if existing_meta_path.exists() else {}
        if avatar_path.is_file() and existing_meta.get("source") == "user_upload":
            return
        picture_url = str(profile.get("picture") or "").strip()
        parsed = urllib.parse.urlparse(picture_url)
        if parsed.scheme != "https" or not (parsed.hostname or "").lower().endswith(("googleusercontent.com", "google.com")):
            return
        request_obj = urllib.request.Request(picture_url, headers={"User-Agent": "IndoAI/1.0", "Accept": "image/jpeg,image/png,image/webp"})
        with urllib.request.urlopen(request_obj, timeout=5) as response:
            content_type = str(response.headers.get("Content-Type", "")).split(";", 1)[0].lower()
            raw = response.read(3 * 1024 * 1024 + 1)
        signatures = {"image/jpeg": b"\xff\xd8\xff", "image/png": b"\x89PNG\r\n\x1a\n", "image/webp": b"RIFF"}
        if content_type not in signatures or not raw or len(raw) > 3 * 1024 * 1024 or not raw.startswith(signatures[content_type]):
            return
        if content_type == "image/webp" and raw[8:12] != b"WEBP":
            return
        temp = avatar_path.with_suffix(".tmp")
        temp.write_bytes(raw)
        os.replace(temp, avatar_path)
        meta_temp = avatar_path.with_suffix(".json.tmp")
        meta_temp.write_text(json.dumps({"media_type": content_type, "source": "google", "updated_at": int(time.time())}), encoding="utf-8")
        os.replace(meta_temp, existing_meta_path)
    except Exception as exc:
        # Login must succeed even if Google's avatar host is temporarily unavailable.
        print("[Indo Google avatar sync skipped]", type(exc).__name__)

@app.get("/api/profile/avatar")
def indo_profile_avatar(request: Request):
    user = _indo_current_user(request)
    if not user:
        return JSONResponse({"error": "Sign in to view your profile photo."}, status_code=401)
    path = _indo_profile_file_for_user(user)
    if not path.is_file():
        return Response(status_code=404, headers={"Cache-Control": "no-store"})
    try:
        meta = json.loads(path.with_suffix(".json").read_text(encoding="utf-8"))
        media_type = meta.get("media_type", "image/jpeg")
    except Exception:
        media_type = "image/jpeg"
    return FileResponse(path, media_type=media_type, headers={"Cache-Control": "no-store, max-age=0"})

@app.post("/api/profile/avatar")
async def indo_upload_profile_avatar(request: Request):
    user = _indo_current_user(request)
    if not user:
        return JSONResponse({"error": "Sign in before uploading a profile photo."}, status_code=401)
    try:
        body = await request.json()
        data_url = str(body.get("data_url") or "")
        if "," not in data_url or not data_url.lower().startswith("data:image/"):
            raise ValueError("Choose a PNG, JPEG, or WebP image.")
        header, encoded = data_url.split(",", 1)
        media_type = header[5:].split(";", 1)[0].lower()
        allowed = {"image/jpeg": ("jpg", b"\xff\xd8\xff"), "image/png": ("png", b"\x89PNG\r\n\x1a\n"), "image/webp": ("webp", b"RIFF")}
        if media_type not in allowed:
            raise ValueError("Only JPEG, PNG, or WebP images are supported.")
        raw = base64.b64decode(encoded, validate=True)
        if not raw or len(raw) > 3 * 1024 * 1024:
            raise ValueError("Profile photos must be 3 MB or smaller.")
        signature = allowed[media_type][1]
        if not raw.startswith(signature) or (media_type == "image/webp" and raw[8:12] != b"WEBP"):
            raise ValueError("That file does not look like a valid image of the selected type.")
    except Exception as exc:
        return JSONResponse({"error": str(exc) if isinstance(exc, ValueError) else "Could not read the selected image."}, status_code=400)
    path = _indo_profile_file_for_user(user)
    temp = path.with_suffix(".tmp")
    temp.write_bytes(raw)
    os.replace(temp, path)
    meta_path = path.with_suffix(".json")
    meta_temp = path.with_suffix(".json.tmp")
    meta_temp.write_text(json.dumps({"media_type": media_type, "source": "user_upload", "updated_at": int(time.time())}), encoding="utf-8")
    os.replace(meta_temp, meta_path)
    return JSONResponse({"ok": True, "avatar_url": "/api/profile/avatar?v=" + str(int(path.stat().st_mtime))})

@app.get("/api/auth/me")
def indo_auth_me(request: Request):
    user = _indo_current_user(request)
    # Never let a cached anonymous response overwrite the real account state after
    # login, especially when the app is reopened after a long idle period.
    linked_account = None
    if user:
        identity = str(user.get("user_key") or "")
        if identity.startswith("google:"):
            conn = _indo_accounts_db()
            try:
                linked_account = conn.execute("SELECT username FROM accounts WHERE linked_google_key=?", (identity,)).fetchone()
            finally:
                conn.close()
        elif user.get("provider") == "indo":
            conn = _indo_accounts_db()
            try:
                linked_account = conn.execute("SELECT username FROM accounts WHERE username_norm=? AND linked_google_key IS NOT NULL", (str(user.get("email") or "").casefold(),)).fetchone()
            finally:
                conn.close()
    avatar_path = _indo_profile_file_for_user(user) if user else None
    response = JSONResponse({"signed_in": bool(user), "email": user.get("email") if user else None,
                             "name": user.get("name") if user else None,
                             "display_name": user.get("name") if user else None,
                             "provider": user.get("provider", "google") if user else None,
                             "google_configured": bool(GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET),
                             "indo_login_available": True,
                             "indo_synced": bool(linked_account),
                             "indo_username": linked_account["username"] if linked_account else None,
                             "avatar_url": "/api/profile/avatar?v=" + str(int(avatar_path.stat().st_mtime)) if avatar_path and avatar_path.is_file() else None,
                             "login_url": "/auth/google/login"})
    response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    return response

@app.post("/auth/indo/register")
async def indo_register(request: Request):
    try:
        body = await request.json()
        username = str(body.get("username") or "").strip()
        password = str(body.get("password") or "")
    except Exception:
        return JSONResponse({"error": "Enter a username and password."}, status_code=400)
    if not re.fullmatch(r"[A-Za-z0-9_.-]{3,24}", username):
        return JSONResponse({"error": "Username must be 3–24 characters: letters, numbers, dots, underscores, or hyphens."}, status_code=400)
    if len(password) < 8 or len(password) > 128:
        return JSONResponse({"error": "Password must be between 8 and 128 characters."}, status_code=400)
    username_norm = username.casefold()
    salt = secrets.token_bytes(16)
    digest = _indo_password_hash(password, salt)
    conn = _indo_accounts_db()
    try:
        conn.execute("INSERT INTO accounts(username_norm, username, password_salt, password_hash, created_at) VALUES(?,?,?,?,?)",
                     (username_norm, username, salt.hex(), digest.hex(), int(time.time())))
        conn.commit()
    except sqlite3.IntegrityError:
        return JSONResponse({"error": "That Indo username already exists. Choose another one or sign in."}, status_code=409)
    finally:
        conn.close()
    token = _indo_make_session(username, username, provider="indo", user_key="indo:" + username_norm)
    response = JSONResponse({"ok": True, "signed_in": True, "name": username, "provider": "indo"})
    _indo_set_login_cookie(response, token)
    return response

@app.post("/auth/indo/login")
async def indo_login(request: Request):
    try:
        body = await request.json()
        username = str(body.get("username") or "").strip()
        password = str(body.get("password") or "")
    except Exception:
        return JSONResponse({"error": "Enter your Indo username and password."}, status_code=400)
    if not username or not password or len(username) > 100 or len(password) > 128:
        return JSONResponse({"error": "Invalid username or password."}, status_code=401)
    conn = _indo_accounts_db()
    try:
        row = conn.execute("SELECT * FROM accounts WHERE username_norm=?", (username.casefold(),)).fetchone()
    finally:
        conn.close()
    if not row:
        return JSONResponse({"error": "Invalid username or password."}, status_code=401)
    try:
        salt = bytes.fromhex(row["password_salt"])
        expected = bytes.fromhex(row["password_hash"])
        actual = _indo_password_hash(password, salt)
    except Exception:
        return JSONResponse({"error": "This account could not be verified. Contact the app owner."}, status_code=500)
    if not hmac.compare_digest(actual, expected):
        return JSONResponse({"error": "Invalid username or password."}, status_code=401)
    linked_key = str(row["linked_google_key"] or "").strip()
    session_email = str(row["linked_google_email"] or row["username"])
    session_name = str(row["username"])
    session_user_key = linked_key if linked_key.startswith("google:") else "indo:" + row["username_norm"]
    token = _indo_make_session(session_email, session_name, provider="indo", user_key=session_user_key)
    response = JSONResponse({"ok": True, "signed_in": True, "name": session_name, "provider": "indo", "linked_google": bool(linked_key)})
    _indo_set_login_cookie(response, token)
    return response

@app.post("/auth/indo/sync")
async def indo_sync_google_account(request: Request):
    user = _indo_current_user(request)
    if not user or user.get("provider") != "google" or not str(user.get("user_key") or "").startswith("google:"):
        return JSONResponse({"error": "First sign in with Google, then use Sync to Indo in Settings."}, status_code=401)
    try:
        body = await request.json()
        username = str(body.get("username") or "").strip()
        password = str(body.get("password") or "")
    except Exception:
        return JSONResponse({"error": "Enter an Indo username and password."}, status_code=400)
    if not re.fullmatch(r"[A-Za-z0-9_.-]{3,24}", username):
        return JSONResponse({"error": "Username must be 3–24 characters: letters, numbers, dots, underscores, or hyphens."}, status_code=400)
    if len(password) < 8 or len(password) > 128:
        return JSONResponse({"error": "Password must be between 8 and 128 characters."}, status_code=400)
    username_norm = username.casefold()
    google_key = str(user.get("user_key"))
    google_email = str(user.get("email") or "")
    conn = _indo_accounts_db()
    try:
        row = conn.execute("SELECT * FROM accounts WHERE username_norm=?", (username_norm,)).fetchone()
        if row:
            salt = bytes.fromhex(row["password_salt"])
            expected = bytes.fromhex(row["password_hash"])
            if not hmac.compare_digest(_indo_password_hash(password, salt), expected):
                return JSONResponse({"error": "That Indo username exists. Enter its correct password to link it."}, status_code=401)
            if row["linked_google_key"] and row["linked_google_key"] != google_key:
                return JSONResponse({"error": "That Indo account is already linked to a different Google account."}, status_code=409)
            conn.execute("UPDATE accounts SET linked_google_key=?, linked_google_email=? WHERE username_norm=?", (google_key, google_email, username_norm))
        else:
            salt = secrets.token_bytes(16)
            digest = _indo_password_hash(password, salt)
            conn.execute("INSERT INTO accounts(username_norm, username, password_salt, password_hash, created_at, linked_google_key, linked_google_email) VALUES(?,?,?,?,?,?,?)",
                         (username_norm, username, salt.hex(), digest.hex(), int(time.time()), google_key, google_email))
        conn.commit()
    except sqlite3.IntegrityError:
        return JSONResponse({"error": "This Google account is already linked to another Indo username."}, status_code=409)
    except Exception:
        return JSONResponse({"error": "Could not sync this account. Please try again."}, status_code=500)
    finally:
        conn.close()
    return JSONResponse({"ok": True, "indo_synced": True, "username": username, "message": "Google and Indo sign-in are now linked. Use this Indo username and password to sign in later."})

@app.get("/auth/google/login")
def indo_google_login(request: Request):
    redirect_uri = _indo_google_callback_uri(request)
    if not (GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET):
        return HTMLResponse(
            "<h2>Google sign-in is not configured yet</h2><p>Set GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET in your hosting environment, and add this exact Authorized redirect URI in Google Cloud Console:</p><code>" +
            __import__("html").escape(redirect_uri) + "</code><p>Then redeploy/restart Indo AI.</p>", status_code=503
        )
    state = secrets.token_urlsafe(32)
    params = {"client_id": GOOGLE_CLIENT_ID, "redirect_uri": redirect_uri,
              "response_type": "code", "scope": "openid email profile", "state": state,
              "prompt": "select_account"}
    location = "https://accounts.google.com/o/oauth2/v2/auth?" + urllib.parse.urlencode(params)
    response = Response(status_code=302, headers={"Location": location})
    response.set_cookie(INDO_OAUTH_STATE_COOKIE, state, httponly=True, samesite="lax",
                        secure=redirect_uri.lower().startswith("https://"), max_age=600, path="/")
    return response

@app.get("/auth/google/callback")
def indo_google_callback(request: Request, code: str = "", state: str = "", error: str = ""):
    redirect_uri = _indo_google_callback_uri(request)
    if error:
        return HTMLResponse("Google sign-in was cancelled or denied. You can close this tab and try again.", status_code=400)
    saved_state = request.cookies.get(INDO_OAUTH_STATE_COOKIE, "")
    if not code or not state or not saved_state or not hmac.compare_digest(state, saved_state):
        return HTMLResponse("Google sign-in could not be verified. Please start again from Indo AI.", status_code=400)
    if not (GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET):
        return HTMLResponse("Google sign-in is not configured. Set GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET.", status_code=503)
    try:
        token_body = urllib.parse.urlencode({"code": code, "client_id": GOOGLE_CLIENT_ID,
            "client_secret": GOOGLE_CLIENT_SECRET, "redirect_uri": redirect_uri,
            "grant_type": "authorization_code"}).encode("utf-8")
        token_req = urllib.request.Request("https://oauth2.googleapis.com/token", data=token_body,
            headers={"Content-Type": "application/x-www-form-urlencoded"}, method="POST")
        with urllib.request.urlopen(token_req, timeout=12) as res:
            token_data = json.loads(res.read(1_000_000).decode("utf-8", "replace"))
        id_token = str(token_data.get("id_token") or "")
        if not id_token:
            raise ValueError("Google did not return an ID token")
        verify_url = "https://oauth2.googleapis.com/tokeninfo?" + urllib.parse.urlencode({"id_token": id_token})
        with urllib.request.urlopen(verify_url, timeout=12) as res:
            claims = json.loads(res.read(1_000_000).decode("utf-8", "replace"))
        email = str(claims.get("email") or "").strip().lower()
        subject = str(claims.get("sub") or "").strip()
        if claims.get("aud") != GOOGLE_CLIENT_ID or claims.get("email_verified") not in (True, "true", "True") or not email or not subject:
            raise ValueError("Google account verification failed")
        # Prefer Google's verified userinfo endpoint for the current display name and picture.
        profile = dict(claims)
        access_token = str(token_data.get("access_token") or "")
        if access_token:
            try:
                info_req = urllib.request.Request("https://openidconnect.googleapis.com/v1/userinfo", headers={"Authorization": "Bearer " + access_token, "Accept": "application/json"})
                with urllib.request.urlopen(info_req, timeout=5) as info_res:
                    info = json.loads(info_res.read(256_000).decode("utf-8", "replace"))
                if str(info.get("sub") or "") == subject:
                    profile.update(info)
            except Exception as profile_exc:
                print("[Indo Google userinfo sync skipped]", type(profile_exc).__name__)
        profile_name = str(profile.get("name") or claims.get("name") or email)[:120]
        user_key = "google:" + subject
        session = _indo_make_session(email, profile_name, provider="google", user_key=user_key)
        try:
            _indo_sync_google_profile({"email": email, "name": profile_name, "provider": "google", "user_key": user_key}, profile)
        except Exception as profile_exc:
            print("[Indo Google profile sync skipped]", type(profile_exc).__name__)
        response = Response(status_code=302, headers={"Location": "/"})
        _indo_set_login_cookie(response, session)
        response.delete_cookie(INDO_OAUTH_STATE_COOKIE, path="/")
        return response
    except Exception as exc:
        print("[Indo Google sign-in error]", type(exc).__name__, str(exc)[:180])
        return HTMLResponse("Google sign-in failed during verification/token exchange. Confirm GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET belong to the same OAuth client, and that this exact Authorized redirect URI is registered in Google Cloud Console: " + __import__("html").escape(redirect_uri) + ". Check the server logs for the non-secret error type, then try again.", status_code=502)

@app.post("/auth/logout")
def indo_logout():
    response = JSONResponse({"ok": True, "signed_in": False})
    response.delete_cookie(INDO_SESSION_COOKIE, path="/")
    # Also clear the previous v5.56 cookie name if an old browser session exists.
    response.delete_cookie("indo_google_session", path="/")
    return response


