# Provider health manager: classify hard quota/billing/auth failures separately
# from transient rate limits and outages. Cooldowns are process-local and never
# alter credentials, user data, or provider accounts.
_INDO_PROVIDER_HEALTH_LOCK = threading.RLock()
_INDO_PROVIDER_COOLDOWN_UNTIL = {}
_INDO_PROVIDER_LAST_ERROR = {}
_INDO_PROVIDER_STATUS = {}
_INDO_PROVIDER_RETRY_AT = {}


def _indo_provider_retry_seconds(exc):
    """Read provider RetryInfo/Retry-After when present, with safe upper bounds."""
    raw = str(exc or "")
    candidates = []
    for pattern in (r"retryDelay['\"]?\s*:\s*['\"](\d+(?:\.\d+)?)s",
                    r"retry[-_ ]after['\"]?\s*[:=]\s*['\"]?(\d+(?:\.\d+)?)"):
        match = re.search(pattern, raw, re.I)
        if match:
            try:
                candidates.append(float(match.group(1)))
            except Exception:
                pass
    try:
        headers = getattr(exc, "headers", None)
        if headers:
            value = headers.get("Retry-After")
            if value:
                candidates.append(float(value))
    except Exception:
        pass
    if not candidates:
        return None
    return max(5, min(int(max(candidates)), 86400))


def _indo_provider_classify_error(exc):
    low = str(exc or "").casefold()
    if any(term in low for term in ("no credits remaining", "insufficient_quota", "billing_hard_limit", "billing limit")):
        return "BILLING_EXHAUSTED"
    if any(term in low for term in ("401", "invalid api key", "incorrect api key", "unauthorized", "authentication failed")):
        return "AUTH_FAILED"
    if any(term in low for term in ("generate_content_free_tier_requests", "requests per day", "perday", "daily quota")) and "429" in low:
        return "QUOTA_EXHAUSTED"
    if any(term in low for term in ("429", "rate limit", "too many requests", "resource_exhausted")):
        return "RATE_LIMITED"
    if any(term in low for term in ("500", "502", "503", "504", "unavailable", "overloaded", "timeout", "timed out", "connection reset", "connection aborted")):
        return "DEGRADED"
    if any(term in low for term in ("403", "permission denied", "forbidden")):
        return "AUTH_FAILED"
    return "DEGRADED"


def _indo_provider_cooldown_seconds(exc):
    status = _indo_provider_classify_error(exc)
    retry = _indo_provider_retry_seconds(exc)
    if status == "QUOTA_EXHAUSTED":
        # Respect Gemini RetryInfo (e.g. 14,586 seconds); never hammer a daily quota.
        return retry or max(3600, min(int(os.getenv("INDO_PROVIDER_DAILY_QUOTA_COOLDOWN", "21600")), 86400))
    if status == "BILLING_EXHAUSTED":
        # Billing exhaustion normally needs user action. Probe at most hourly.
        return max(900, min(int(os.getenv("INDO_PROVIDER_BILLING_COOLDOWN", "3600")), 86400))
    if status == "AUTH_FAILED":
        return max(900, min(int(os.getenv("INDO_PROVIDER_AUTH_COOLDOWN", "3600")), 86400))
    if status == "RATE_LIMITED":
        return retry or max(30, min(int(os.getenv("INDO_PROVIDER_RATE_COOLDOWN", "90")), 1800))
    return max(10, min(int(os.getenv("INDO_PROVIDER_ERROR_COOLDOWN", "30")), 300))


def _indo_provider_mark_failure(name, exc):
    now = time.monotonic()
    status = _indo_provider_classify_error(exc)
    cooldown = _indo_provider_cooldown_seconds(exc)
    with _INDO_PROVIDER_HEALTH_LOCK:
        _INDO_PROVIDER_COOLDOWN_UNTIL[name] = now + cooldown
        _INDO_PROVIDER_RETRY_AT[name] = now + cooldown
        _INDO_PROVIDER_STATUS[name] = status
        _INDO_PROVIDER_LAST_ERROR[name] = _provider_error_text(name, exc)
    print(f"[Indo provider health] {name}: {status}; retry probe in about {cooldown}s")


def _indo_provider_mark_success(name):
    with _INDO_PROVIDER_HEALTH_LOCK:
        _INDO_PROVIDER_COOLDOWN_UNTIL.pop(name, None)
        _INDO_PROVIDER_RETRY_AT.pop(name, None)
        _INDO_PROVIDER_STATUS[name] = "HEALTHY"
        _INDO_PROVIDER_LAST_ERROR.pop(name, None)


def _indo_provider_is_available(name):
    with _INDO_PROVIDER_HEALTH_LOCK:
        return _INDO_PROVIDER_COOLDOWN_UNTIL.get(name, 0.0) <= time.monotonic()


def _indo_provider_health_snapshot():
    """Safe diagnostics only; never returns credentials or raw provider payloads."""
    now = time.monotonic()
    output = {}
    with _INDO_PROVIDER_HEALTH_LOCK:
        for name in set(PROVIDERS) | set(_INDO_PROVIDER_STATUS):
            remaining = max(0, int(_INDO_PROVIDER_COOLDOWN_UNTIL.get(name, 0.0) - now))
            output[name] = {
                "status": _INDO_PROVIDER_STATUS.get(name, "HEALTHY" if provider_configured(name) else "NOT_CONFIGURED"),
                "available": remaining == 0 and provider_configured(name),
                "retry_in_seconds": remaining,
                "last_error": _INDO_PROVIDER_LAST_ERROR.get(name, ""),
            }
    return output


def _ordered_configured_providers():
    """Return healthy providers only; never retry a known exhausted provider as last resort."""
    configured = [name for name in PROVIDERS if provider_configured(name)]
    preferred = os.getenv("INDO_PRIMARY_PROVIDER", "gemini").strip().lower()
    if preferred in configured:
        configured = [preferred] + [name for name in configured if name != preferred]
    now = time.monotonic()
    with _INDO_PROVIDER_HEALTH_LOCK:
        healthy = [name for name in configured if _INDO_PROVIDER_COOLDOWN_UNTIL.get(name, 0.0) <= now]
    return healthy

def _retryable_error(exc):
    """Return True for transient provider failures that may succeed on retry."""
    low = str(exc).lower()
    return any(x in low for x in (
        "429", "quota", "resource_exhausted", "500", "502", "503", "504",
        "unavailable", "overloaded", "timeout", "timed out", "connection reset",
        "connection aborted", "temporarily", "internal error", "server error",
    ))


def _model_missing_error(exc):
    low = str(exc).lower()
    return ("404" in low or "not found" in low or "unknown model" in low
            or "is not supported" in low or "model is unavailable" in low)


def _provider_error_text(name, exc):
    """Return user-safe, provider-neutral diagnostics; never expose vendor names or raw errors."""
    low = str(exc).lower()
    if any(x in low for x in ("no credits remaining", "insufficient_quota", "billing_hard_limit", "billing limit")):
        return "The provider account has no API credits remaining. Add API credits or check billing before retrying."
    if "generate_content_free_tier_requests" in low or "requests per day" in low or "daily quota" in low:
        return "The provider's daily request quota has been reached. Indo will wait for the quota cooldown before retrying."
    if any(x in low for x in ("429", "quota", "resource_exhausted", "rate limit", "too many requests")):
        return "The provider is temporarily rate-limited. Indo will respect its retry window before trying again."
    if any(x in low for x in ("401", "403", "unauthorized", "api key", "permission denied", "invalid key", "authentication failed", "access denied")):
        if name == "openai":
            return "OpenAI authentication failed. Check the local INDO_OPENAI_API_KEY value and confirm it is active; this is not a usage-limit error."
        if name == "gemini":
            return "Gemini authentication or project permission failed. Check GEMINI_API_KEY and its API access."
        if name == "ollama":
            return "Ollama Cloud authentication or model permission failed. Check OLLAMA_API_KEY and the configured cloud model."
        return "A service authentication or permission issue prevented the response. Check that provider's configuration."
    if any(x in low for x in ("404", "not found", "unknown model", "is not supported", "model is unavailable")):
        return "The requested service is temporarily unavailable. Please try again later."
    if "timeout" in low or "timed out" in low:
        return "The request took too long to complete. Please try again."
    if any(x in low for x in ("connection", "network", "dns", "socket")):
        return "A temporary connection problem occurred. Check your internet connection and try again."
    return "A temporary service problem prevented the response. Please try again in a little while."


def _post_json(url, payload, headers=None, timeout=None):
    req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"), method="POST", headers={"Content-Type":"application/json", **(headers or {})})
    return urllib.request.urlopen(req, timeout=PROVIDER_TIMEOUT if timeout is None else timeout)


def _openai_stream(prompt, deep=False):
    """Stream OpenAI output with bounded token-limit and transport recovery.

    First-segment text is streamed immediately. Recovery segments are buffered,
    overlap-trimmed, then appended so retries cannot visibly duplicate the answer.
    """
    if not OPENAI_API_KEY:
        raise RuntimeError("OpenAI API key is not configured")
    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}", "Accept": "text/event-stream"}
    ultra_fast_max_tokens = max(128, min(int(os.getenv("INDO_ULTRA_FAST_MAX_OUTPUT_TOKENS", "320")), 512))
    max_tokens = 512 if "[VOICE CHAT STYLE:" in str(prompt) else (
        DEEP_MAX_OUTPUT_TOKENS if deep or "[INDO DEEP MODE]" in str(prompt) else
        (ultra_fast_max_tokens if "[INDO ULTRA FAST MODE]" in str(prompt) else FAST_MAX_OUTPUT_TOKENS)
    )
    timeout = INDO_DEEP_OPENAI_TIMEOUT if deep else OPENAI_PROVIDER_TIMEOUT
    continuation_limit = configured_continuation_limit()
    messages = [{"role": "user", "content": str(prompt)}]
    complete_text = ""
    soft_recovery_used = False

    for segment_index in range(continuation_limit + 1):
        payload = {
            "model": OPENAI_MODEL,
            "messages": messages,
            "stream": True,
            "temperature": 0.72,
            "max_tokens": max_tokens,
        }
        segment_text = ""
        finish_reason = None
        stream_error = None
        try:
            with _post_json(OPENAI_BASE_URL + "/chat/completions", payload, headers, timeout=timeout) as r:
                for raw in r:
                    line = raw.decode("utf-8", errors="replace").strip()
                    if not line.startswith("data:"):
                        continue
                    data = line[5:].strip()
                    if data == "[DONE]":
                        break
                    try:
                        obj = json.loads(data)
                    except Exception:
                        continue
                    choices = obj.get("choices") or []
                    if not choices:
                        continue
                    choice = choices[0] or {}
                    reason = choice.get("finish_reason")
                    if reason is not None:
                        finish_reason = finish_reason_name(reason)
                    delta = choice.get("delta") or {}
                    piece = delta.get("content")
                    if isinstance(piece, str) and piece:
                        if segment_index == 0:
                            complete_text += piece
                            yield piece
                        else:
                            segment_text += piece
        except urllib.error.HTTPError as exc:
            if is_retryable_stream_error(exc) and (complete_text or segment_text) and segment_index < continuation_limit:
                stream_error = exc
            else:
                try:
                    raw_body = exc.read(4096).decode("utf-8", errors="replace")
                    body = json.loads(raw_body) if raw_body else {}
                    detail = body.get("error", {}) if isinstance(body, dict) else {}
                    message = str(detail.get("message") or detail.get("code") or detail.get("type") or "") if isinstance(detail, dict) else str(detail)
                except Exception:
                    message = ""
                if exc.code == 401:
                    raise RuntimeError("OpenAI authentication failed (HTTP 401). Check that INDO_OPENAI_API_KEY is valid and active. Provider message: " + message[:240]) from exc
                if exc.code == 403:
                    raise RuntimeError("OpenAI access denied (HTTP 403). Check API project permissions and model access. Provider message: " + message[:240]) from exc
                raise RuntimeError(f"OpenAI API returned HTTP {exc.code}. Provider message: {message[:240]}") from exc
        except Exception as exc:
            if is_retryable_stream_error(exc) and (complete_text or segment_text) and segment_index < continuation_limit:
                stream_error = exc
            else:
                raise

        if segment_index > 0 and segment_text:
            addition = trim_continuation_overlap(complete_text, segment_text)
            if addition:
                complete_text += addition
                yield addition

        explicit_limit = is_length_finish_reason(finish_reason)
        suspicious_tail = should_continue_response(finish_reason, complete_text)
        if suspicious_tail and soft_recovery_used and not explicit_limit and not stream_error:
            raise RuntimeError("OpenAI response still appears unfinished after its soft continuation.")
        needs_recovery = bool(stream_error) or explicit_limit or (suspicious_tail and not soft_recovery_used)
        if not needs_recovery:
            if segment_index:
                print(f"[Indo OpenAI completion] continued_segments={segment_index} finish_reason={finish_reason or 'unknown'}")
            return

        if segment_index >= continuation_limit:
            reason = "transport interruption" if stream_error else (f"finish_reason={finish_reason}" if explicit_limit else "unfinished response ending")
            raise RuntimeError(f"OpenAI response remained incomplete after {segment_index} continuation attempt(s) ({reason}).")

        if not explicit_limit and not stream_error:
            soft_recovery_used = True
        if stream_error:
            print(f"[Indo OpenAI completion] recovering interrupted stream ({type(stream_error).__name__})")
        elif explicit_limit:
            print("[Indo OpenAI completion] provider reached output-token limit; requesting continuation")
        else:
            print("[Indo OpenAI completion] response ended with an incomplete structure; requesting one continuation")

        messages = [
            {"role": "user", "content": str(prompt)},
            {"role": "assistant", "content": complete_text},
            {"role": "user", "content": CONTINUATION_INSTRUCTION},
        ]


def _ollama_local_stream(prompt):
    """Optional local Ollama adapter; used only when INDO_OLLAMA_MODE=local."""
    payload = {
        "model": OLLAMA_MODEL,
        "prompt": str(prompt),
        "stream": True,
        "options": {"temperature": 0.72},
    }
    emitted = False
    try:
        with _post_json(
            OLLAMA_BASE_URL + "/api/generate",
            payload,
            timeout=OLLAMA_PROVIDER_TIMEOUT,
        ) as response:
            for raw in response:
                try:
                    obj = json.loads(raw.decode("utf-8", errors="replace"))
                except Exception:
                    continue
                if obj.get("error"):
                    raise RuntimeError("Local Ollama model error: " + str(obj["error"])[:220])
                piece = obj.get("response")
                if isinstance(piece, str) and piece:
                    emitted = True
                    yield piece
                if obj.get("done"):
                    break
    except urllib.error.HTTPError as exc:
        try:
            detail = exc.read(2048).decode("utf-8", errors="replace")
        except Exception:
            detail = ""
        if exc.code == 404:
            raise RuntimeError(
                f"Local model '{OLLAMA_MODEL}' is not installed in Ollama. "
                f"Run: ollama pull {OLLAMA_MODEL}"
            ) from exc
        raise RuntimeError(f"Local Ollama server returned HTTP {exc.code}: {detail[:180]}") from exc
    except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as exc:
        raise RuntimeError(
            "Local Ollama server is not reachable. Start Ollama and check INDO_OLLAMA_BASE_URL."
        ) from exc
    if not emitted:
        raise RuntimeError("The local Ollama model returned an empty response.")


def _ollama_cloud_stream(prompt, deep=False):
    """Stream from Ollama Cloud directly; no local Ollama install/model download."""
    if not OLLAMA_API_KEY:
        raise RuntimeError("Ollama Cloud API key is not configured")
    headers = {"Authorization": f"Bearer {OLLAMA_API_KEY}", "Accept": "text/event-stream"}
    max_tokens = DEEP_MAX_OUTPUT_TOKENS if deep or "[INDO DEEP MODE]" in str(prompt) else FAST_MAX_OUTPUT_TOKENS
    continuation_limit = configured_continuation_limit()
    messages = [{"role": "user", "content": str(prompt)}]
    complete_text = ""
    soft_recovery_used = False

    for segment_index in range(continuation_limit + 1):
        payload = {
            "model": OLLAMA_MODEL,
            "messages": messages,
            "stream": True,
            "temperature": 0.72,
            "max_tokens": max_tokens,
        }
        segment_text = ""
        finish_reason = None
        try:
            with _post_json(OLLAMA_BASE_URL + "/chat/completions", payload, headers, timeout=OLLAMA_PROVIDER_TIMEOUT) as response:
                for raw in response:
                    line = raw.decode("utf-8", errors="replace").strip()
                    if not line.startswith("data:"):
                        continue
                    data = line[5:].strip()
                    if data == "[DONE]":
                        break
                    try:
                        obj = json.loads(data)
                    except Exception:
                        continue
                    choices = obj.get("choices") or []
                    if not choices:
                        continue
                    choice = choices[0] or {}
                    if choice.get("finish_reason") is not None:
                        finish_reason = finish_reason_name(choice.get("finish_reason"))
                    delta = choice.get("delta") or {}
                    piece = delta.get("content")
                    if isinstance(piece, str) and piece:
                        if segment_index == 0:
                            complete_text += piece
                            yield piece
                        else:
                            segment_text += piece
        except urllib.error.HTTPError as exc:
            try:
                raw_body = exc.read(4096).decode("utf-8", errors="replace")
                body = json.loads(raw_body) if raw_body else {}
                detail = body.get("error", {}) if isinstance(body, dict) else {}
                message = str(detail.get("message") or detail.get("code") or detail)[:260]
            except Exception:
                message = ""
            if exc.code in (401, 403):
                raise RuntimeError("Ollama Cloud authentication or model permission failed. Check OLLAMA_API_KEY and model access. " + message) from exc
            if exc.code == 429:
                raise RuntimeError("Ollama Cloud rate or usage limit reached. Respect the provider retry window. " + message) from exc
            raise RuntimeError(f"Ollama Cloud returned HTTP {exc.code}. {message}") from exc

        if segment_index > 0 and segment_text:
            addition = trim_continuation_overlap(complete_text, segment_text)
            if addition:
                complete_text += addition
                yield addition
        if not complete_text.strip():
            raise RuntimeError("Ollama Cloud returned an empty response.")

        explicit_limit = is_length_finish_reason(finish_reason)
        suspicious_tail = should_continue_response(finish_reason, complete_text)
        needs_recovery = explicit_limit or (suspicious_tail and not soft_recovery_used)
        if not needs_recovery:
            if segment_index:
                print(f"[Indo Ollama Cloud completion] continued_segments={segment_index} finish_reason={finish_reason or 'unknown'}")
            return
        if segment_index >= continuation_limit:
            raise RuntimeError(f"Ollama Cloud response remained incomplete after {segment_index} continuation attempt(s).")
        if not explicit_limit:
            soft_recovery_used = True
        print("[Indo Ollama Cloud completion] requesting continuation after truncated or unfinished response")
        messages = [
            {"role": "user", "content": str(prompt)},
            {"role": "assistant", "content": complete_text},
            {"role": "user", "content": CONTINUATION_INSTRUCTION},
        ]


def _ollama_stream(prompt, deep=False):
    if INDO_OLLAMA_MODE == "local":
        yield from _ollama_local_stream(prompt)
    else:
        yield from _ollama_cloud_stream(prompt, deep=deep)


# Keep Gemini clients alive across requests to reuse their HTTP connection pools.
# Keys remain server-side and are never logged or returned to the browser.
_GEMINI_CLIENT_CACHE = {}
_GEMINI_CLIENT_CACHE_LOCK = threading.Lock()
_GEMINI_CLIENT_CACHE_LIMIT = 8

def _get_cached_gemini_client(api_key, timeout_seconds=None):
    effective_timeout = float(timeout_seconds if timeout_seconds is not None else GEMINI_PROVIDER_TIMEOUT)
    cache_key = (str(api_key), int(effective_timeout * 1000))
    with _GEMINI_CLIENT_CACHE_LOCK:
        cached = _GEMINI_CLIENT_CACHE.get(cache_key)
        if cached is not None:
            return cached
        try:
            http_options = types.HttpOptions(timeout=cache_key[1]) if types and hasattr(types, "HttpOptions") else None
            client = genai.Client(api_key=api_key, **({"http_options": http_options} if http_options else {}))
        except TypeError:
            # Older google-genai SDK compatibility.
            client = genai.Client(api_key=api_key)
        if len(_GEMINI_CLIENT_CACHE) >= _GEMINI_CLIENT_CACHE_LIMIT:
            _GEMINI_CLIENT_CACHE.pop(next(iter(_GEMINI_CLIENT_CACHE)))
        _GEMINI_CLIENT_CACHE[cache_key] = client
        return client


def _gemini_stream(prompt, deep=False, attachments=None):
    """Gemini streaming with bounded token-limit, tail and transport recovery."""
    if genai is None:
        raise RuntimeError("google-genai package is not installed")
    if not API_KEYS:
        raise RuntimeError("No Gemini API key configured")

    key_index = 0
    is_voice_chat = "[VOICE CHAT STYLE:" in str(prompt)
    is_ultra_fast = "[INDO ULTRA FAST MODE]" in str(prompt)
    ultra_fast_max_tokens = max(128, min(int(os.getenv("INDO_ULTRA_FAST_MAX_OUTPUT_TOKENS", "320")), 512))
    max_tokens = 512 if is_voice_chat else (
        ultra_fast_max_tokens if is_ultra_fast else (DEEP_MAX_OUTPUT_TOKENS if deep else FAST_MAX_OUTPUT_TOKENS)
    )
    request_timeout = INDO_DEEP_GEMINI_TIMEOUT if deep else GEMINI_PROVIDER_TIMEOUT
    continuation_limit = configured_continuation_limit()

    fallback_models = [x.strip() for x in os.getenv("INDO_FALLBACK_MODELS", "gemini-3.6-flash").split(",") if x.strip()]
    models = list(dict.fromkeys([MODEL] + [m for m in fallback_models if m != MODEL]))
    models = models[:max(1, min(int(os.getenv("INDO_GEMINI_MAX_MODEL_FALLBACKS", "1")) + 1, 3))]

    base_contents = [prompt]
    for attachment in (attachments or []):
        try:
            mime = str(getattr(attachment, "file_type", "") or "").split(";")[0].strip().lower()
            encoded = getattr(attachment, "data_b64", None)
            if encoded and mime and (mime.startswith("image/") or mime == "application/pdf"):
                raw = base64.b64decode(encoded, validate=True)
                if raw:
                    base_contents.append(types.Part.from_bytes(data=raw, mime_type=mime))
        except Exception as attach_exc:
            print("[Indo AI attachment processing warning]", type(attach_exc).__name__)

    last_error = None
    for model_index, model_name in enumerate(models):
        candidate_key = API_KEYS[key_index]
        candidate_client = _get_cached_gemini_client(candidate_key, timeout_seconds=request_timeout)
        config_kwargs = {"temperature": 0.35 if is_ultra_fast else 0.55, "max_output_tokens": max_tokens}
        model_lower = str(model_name).lower()
        if types and hasattr(types, "ThinkingConfig"):
            try:
                if model_lower.startswith(("gemini-3", "gemini-4")):
                    config_kwargs["thinking_config"] = types.ThinkingConfig(thinking_level="high" if deep else "minimal")
                elif model_lower.startswith("gemini-2.5"):
                    config_kwargs["thinking_config"] = types.ThinkingConfig(thinking_budget=1024 if deep else 0)
            except Exception:
                config_kwargs.pop("thinking_config", None)

        emitted_any = False
        complete_text = ""
        soft_recovery_used = False
        try:
            for segment_index in range(continuation_limit + 1):
                if segment_index == 0:
                    request_contents = list(base_contents)
                else:
                    request_contents = list(base_contents)
                    try:
                        model_part = types.Part(text=complete_text)
                        user_part = types.Part(text=CONTINUATION_INSTRUCTION)
                        request_contents.append(types.Content(role="model", parts=[model_part]))
                        request_contents.append(types.Content(role="user", parts=[user_part]))
                    except Exception:
                        request_contents.append(
                            "Previous partial answer (continue without repeating it):\n" + complete_text +
                            "\n\n" + CONTINUATION_INSTRUCTION
                        )

                segment_text = ""
                finish_reason = None
                stream_error = None
                try:
                    response = candidate_client.models.generate_content_stream(
                        model=model_name,
                        contents=request_contents,
                        config=types.GenerateContentConfig(**config_kwargs),
                    )
                    for chunk in response:
                        candidates = getattr(chunk, "candidates", None) or []
                        for candidate in candidates:
                            candidate_reason = getattr(candidate, "finish_reason", None)
                            if candidate_reason is not None:
                                finish_reason = finish_reason_name(candidate_reason)
                        chunk_text = getattr(chunk, "text", None)
                        if chunk_text:
                            emitted_any = True
                            if segment_index == 0:
                                complete_text += chunk_text
                                yield chunk_text
                            else:
                                segment_text += chunk_text
                except Exception as exc:
                    if is_retryable_stream_error(exc) and (complete_text or segment_text) and segment_index < continuation_limit:
                        stream_error = exc
                    else:
                        raise

                if segment_index > 0 and segment_text:
                    addition = trim_continuation_overlap(complete_text, segment_text)
                    if addition:
                        complete_text += addition
                        yield addition

                explicit_limit = is_length_finish_reason(finish_reason)
                suspicious_tail = should_continue_response(finish_reason, complete_text)
                if suspicious_tail and soft_recovery_used and not explicit_limit and not stream_error:
                    raise RuntimeError("Gemini response still appears unfinished after its soft continuation.")
                needs_recovery = bool(stream_error) or explicit_limit or (suspicious_tail and not soft_recovery_used)
                if not needs_recovery:
                    if segment_index:
                        print(f"[Indo Gemini completion] model={model_name} continued_segments={segment_index} finish_reason={finish_reason or 'unknown'}")
                    print(f"[Indo Gemini] model={model_name} fallback_index={model_index} deep={bool(deep)}")
                    return

                if segment_index >= continuation_limit:
                    reason = "transport interruption" if stream_error else (f"finish_reason={finish_reason}" if explicit_limit else "unfinished response ending")
                    raise RuntimeError(f"Gemini response remained incomplete after {segment_index} continuation attempt(s) ({reason}).")

                if not explicit_limit and not stream_error:
                    soft_recovery_used = True
                if stream_error:
                    print(f"[Indo Gemini completion] recovering interrupted stream ({type(stream_error).__name__})")
                elif explicit_limit:
                    print("[Indo Gemini completion] provider reached output-token limit; requesting continuation")
                else:
                    print("[Indo Gemini completion] response ended with an incomplete structure; requesting one continuation")

        except Exception as exc:
            last_error = exc
            low = str(exc).lower()
            quota_error = any(term in low for term in ("429", "quota", "resource_exhausted", "rate limit", "too many requests"))
            if emitted_any or quota_error or model_index >= len(models) - 1:
                raise
            print(f"[Indo Gemini] model={model_name} failed before output; trying one sequential fallback ({type(exc).__name__})")

    if last_error:
        raise last_error
    raise RuntimeError("No Gemini model could complete the request")


def _provider_stream(name, prompt, deep=False, attachments=None):
    """Stream from one provider and update health for subsequent requests."""
    try:
        if name == "gemini":
            yield from _gemini_stream(prompt, deep=deep, attachments=attachments)
        elif name == "openai":
            yield from _openai_stream(prompt, deep=deep)
        elif name == "ollama":
            yield from _ollama_stream(prompt, deep=deep)
        else:
            raise RuntimeError("Unknown provider: " + name)
        _indo_provider_mark_success(name)
    except GeneratorExit:
        raise
    except Exception as exc:
        _indo_provider_mark_failure(name, exc)
        raise


