# Account-scoped cloud conversation sync. Browser localStorage remains a local cache;
# this SQLite store makes signed-in conversations available across devices/browsers.
INDO_CLOUD_SESSIONS_DB = INDO_AUTH_DIR / "cloud_sessions.sqlite3"
_INDO_CLOUD_SESSIONS_LOCK = threading.RLock()
_INDO_CLOUD_SESSIONS_MAX = 30
_INDO_CLOUD_SESSION_BYTES_MAX = 4_500_000


def _indo_cloud_sessions_connect():
    conn = sqlite3.connect(str(INDO_CLOUD_SESSIONS_DB), timeout=15)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout=15000")
    conn.execute("""CREATE TABLE IF NOT EXISTS account_sessions (
        user_key_hash TEXT PRIMARY KEY,
        sessions_json TEXT NOT NULL DEFAULT '[]',
        deleted_ids_json TEXT NOT NULL DEFAULT '[]',
        updated_at INTEGER NOT NULL
    )""")
    conn.commit()
    return conn


def _indo_cloud_session_identity(user: dict) -> str:
    identity = str(user.get("user_key") or (str(user.get("provider") or "account") + ":" + str(user.get("email") or ""))).strip().casefold()
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()


def _indo_cloud_session_clean(session):
    if not isinstance(session, dict):
        return None
    sid = str(session.get("id") or "").strip()[:160]
    messages = session.get("messages")
    if not sid or not isinstance(messages, list):
        return None
    clean_messages = []
    for message in messages[-300:]:
        if not isinstance(message, dict):
            continue
        content = message.get("content", "")
        if not isinstance(content, str):
            content = str(content or "")
        clean = dict(message)
        clean["content"] = content[:50000]
        clean_messages.append(clean)
    if not any(str(m.get("content") or "").strip() for m in clean_messages):
        return None
    clean = dict(session)
    clean["id"] = sid
    clean["title"] = str(session.get("title") or "New Conversation")[:120]
    clean["titleManuallySet"] = bool(session.get("titleManuallySet", False))
    clean["mode"] = str(session.get("mode") or "New Chat")[:80]
    clean["messages"] = clean_messages
    clean["updatedAt"] = int(session.get("updatedAt") or session.get("updated_at") or 0)
    return clean


@app.get("/api/sessions")
async def indo_cloud_sessions_get(request: Request):
    user = _indo_current_user(request)
    if not user:
        return JSONResponse({"error": "Sign in to sync your conversations.", "sign_in_required": True}, status_code=401)
    key = _indo_cloud_session_identity(user)
    with _INDO_CLOUD_SESSIONS_LOCK:
        conn = _indo_cloud_sessions_connect()
        try:
            row = conn.execute("SELECT sessions_json, deleted_ids_json, updated_at FROM account_sessions WHERE user_key_hash=?", (key,)).fetchone()
            if not row:
                return JSONResponse({"ok": True, "sessions": [], "deleted_ids": [], "updated_at": 0})
            try: sessions = json.loads(row["sessions_json"] or "[]")
            except Exception: sessions = []
            try: deleted = json.loads(row["deleted_ids_json"] or "[]")
            except Exception: deleted = []
            return JSONResponse({"ok": True, "sessions": sessions if isinstance(sessions, list) else [],
                                 "deleted_ids": deleted if isinstance(deleted, list) else [],
                                 "updated_at": int(row["updated_at"] or 0)})
        finally:
            conn.close()


@app.post("/api/sessions")
async def indo_cloud_sessions_save(request: Request):
    user = _indo_current_user(request)
    if not user:
        return JSONResponse({"error": "Sign in to sync your conversations.", "sign_in_required": True}, status_code=401)
    raw = await request.body()
    if len(raw) > _INDO_CLOUD_SESSION_BYTES_MAX:
        return JSONResponse({"error": "Conversation sync payload is too large. Your local chat history is still saved in this browser."}, status_code=413)
    try:
        body = json.loads(raw.decode("utf-8"))
    except Exception:
        return JSONResponse({"error": "Invalid conversation sync payload."}, status_code=400)
    incoming = body.get("sessions", []) if isinstance(body, dict) else []
    deleted_in = body.get("deleted_ids", []) if isinstance(body, dict) else []
    if not isinstance(incoming, list) or not isinstance(deleted_in, list):
        return JSONResponse({"error": "Invalid conversation sync format."}, status_code=400)
    clean_in = [x for x in (_indo_cloud_session_clean(item) for item in incoming[:_INDO_CLOUD_SESSIONS_MAX]) if x]
    deleted = {str(x)[:160] for x in deleted_in[:500] if isinstance(x, str) and x.strip()}
    key = _indo_cloud_session_identity(user)
    with _INDO_CLOUD_SESSIONS_LOCK:
        conn = _indo_cloud_sessions_connect()
        try:
            row = conn.execute("SELECT sessions_json, deleted_ids_json FROM account_sessions WHERE user_key_hash=?", (key,)).fetchone()
            try: existing = json.loads(row["sessions_json"] or "[]") if row else []
            except Exception: existing = []
            try: old_deleted = json.loads(row["deleted_ids_json"] or "[]") if row else []
            except Exception: old_deleted = []
            deleted.update(str(x)[:160] for x in old_deleted if isinstance(x, str))
            merged = {}
            for item in existing if isinstance(existing, list) else []:
                clean = _indo_cloud_session_clean(item)
                if clean and clean["id"] not in deleted: merged[clean["id"]] = clean
            for item in clean_in:
                if item["id"] in deleted: continue
                previous = merged.get(item["id"])
                if previous is None or (item.get("updatedAt", 0), len(item["messages"])) >= (previous.get("updatedAt", 0), len(previous["messages"])):
                    merged[item["id"]] = item
            sessions = sorted(merged.values(), key=lambda x: (int(x.get("updatedAt") or 0), len(x.get("messages") or [])), reverse=True)[:_INDO_CLOUD_SESSIONS_MAX]
            payload = json.dumps(sessions, ensure_ascii=False, separators=(",", ":"))
            while len(payload.encode("utf-8")) > _INDO_CLOUD_SESSION_BYTES_MAX and sessions:
                sessions.pop()
                payload = json.dumps(sessions, ensure_ascii=False, separators=(",", ":"))
            now = int(time.time())
            conn.execute("""INSERT INTO account_sessions(user_key_hash,sessions_json,deleted_ids_json,updated_at)
                VALUES(?,?,?,?) ON CONFLICT(user_key_hash) DO UPDATE SET
                sessions_json=excluded.sessions_json, deleted_ids_json=excluded.deleted_ids_json, updated_at=excluded.updated_at""",
                (key, payload, json.dumps(sorted(deleted)[-500:]), now))
            conn.commit()
            return JSONResponse({"ok": True, "synced": len(sessions), "deleted": len(deleted), "updated_at": now})
        finally:
            conn.close()


def _dataset_save(question, answer, mode="New Chat"):
    """Save a completed, useful Q&A locally. Sensitive/private-looking text is skipped."""
    if not DATASET_ENABLED:
        return False
    question = str(question or "").strip()
    answer = str(answer or "").strip()
    normalized = _normalize_dataset_text(question)
    if not normalized or not answer or len(normalized) < 2:
        return False
    if len(question) > 2500 or len(answer) > 16000:
        return False
    if _looks_like_private_or_sensitive_content(question) or _looks_like_private_or_sensitive_content(answer):
        return False
    # Never copy explicit personal-memory/profile statements into the shared reusable Q&A cache.
    try:
        if _indo_memory_fact_from_message(question) or _indo_memory_clear_requested(question):
            return False
    except Exception:
        pass
    # Never cache transient research answers as reusable facts: those can go stale.
    if "[[indo_sources_json]]" in answer.casefold() or "Sources above were fetched" in answer:
        return False
    try:
        with _DATASET_LOCK, _dataset_connect() as conn:
            conn.execute("""INSERT INTO answer_dataset(normalized_question, question, answer, mode)
                VALUES(?,?,?,?)
                ON CONFLICT(normalized_question) DO UPDATE SET
                    question=excluded.question,
                    answer=excluded.answer,
                    mode=excluded.mode,
                    created_at=CURRENT_TIMESTAMP""",
                (normalized, question[:2500], answer[:16000], str(mode or "New Chat")[:80]))
        return True
    except Exception as exc:
        print("[Indo AI dataset save error]", repr(exc))
        return False


def _dataset_save_async(question, answer, mode="New Chat"):
    """Persist reusable answers off the response path so SQLite work cannot delay stream completion."""
    try:
        threading.Thread(
            target=_dataset_save,
            args=(str(question or ""), str(answer or ""), str(mode or "New Chat")),
            name="indo-dataset-save",
            daemon=True,
        ).start()
    except Exception as exc:
        print("[Indo AI async dataset save warning]", repr(exc))


def _language_response_rule(message):
    """Prefer the language used by the current user turn, not a memorized Hinglish persona."""
    value = str(message or "").strip()
    if not value:
        return "Reply in the language used by the user."
    if re.search(r"[\u0900-\u097F]", value):
        return "LANGUAGE RULE (HIGH PRIORITY): The current message contains Devanagari Hindi. Reply in natural Hindi, or mixed Hindi-English only if the user themselves code-switches."
    words = re.findall(r"[a-z]+", value.lower())
    roman_hindi = re.findall(r"\b(bhai|kya|kyu|kyun|kaise|kaisa|hai|hain|ho|haan|nahi|nahin|mera|meri|tera|teri|tum|aap|mujhe|yaar|bahut|bohot|achha|acha|theek|suna|batao|karna|karo|raha|rahe|rhi|matlab|aur|toh|kyunki)\b", value.lower())
    if len(roman_hindi) >= 2 and len(roman_hindi) / max(len(words), 1) >= 0.18:
        return "LANGUAGE RULE (HIGH PRIORITY): The user is using Roman-Hindi/Hinglish. Reply naturally in the same mix; do not force pure Hindi if the user uses mostly English."
    return "LANGUAGE RULE (HIGH PRIORITY): Reply in English because the current user message is in English or uses English slang. Do not switch to Hindi/Hinglish just because the user says 'bro', 'bhai', 'hi', 'wsp', or similar greetings. Example: for 'hi bro wsp', answer in English, such as 'Yo bro, I’m good! What’s up with you?'"


def _is_casual_greeting(message):
    normalized = _normalize_dataset_text(message)
    if len(normalized.split()) > 10:
        return False
    patterns = (
        r"^(hi|hey|hello|hii|hiii|yo|sup|wsp)( bhai| bro| dude| there)?$",
        r"^(hi|hey|hello|hii|hiii|yo|sup|wsp) (bro|bhai) (wsp|what'?s up|how are you|how you doing)$",
        r"^(hi|hey|hello|hii|hiii|yo|sup|wsp) (bhai|bro) (kaisa hai|kaise ho|kya haal( hai)?|kya scene( hai)?)$",
        r"^(bhai )?(kaisa hai|kaise ho|kya haal|kya scene|sab badhiya)$",
        r"^(good morning|good evening|good night)( bhai| bro)?$",
    )
    return any(re.match(pattern, normalized) for pattern in patterns)


def _dataset_lookup(message, mode="New Chat", allow_similar=True):
    """Exact match for context-free queries; fuzzy matching is restricted to greetings."""
    if not DATASET_ENABLED:
        return None
    normalized = _normalize_dataset_text(message)
    if not normalized:
        return None
    try:
        with _DATASET_LOCK, _dataset_connect() as conn:
            row = conn.execute(
                "SELECT id, question, answer FROM answer_dataset WHERE normalized_question=? AND mode IN (?, 'New Chat') ORDER BY created_at DESC LIMIT 1",
                (normalized, str(mode or "New Chat")[:80]),
            ).fetchone()
            if row:
                conn.execute("UPDATE answer_dataset SET use_count=use_count+1,last_used_at=CURRENT_TIMESTAMP WHERE id=?", (row[0],))
                return {"answer": row[2], "match": "exact", "question": row[1]}
            if not allow_similar or not _is_casual_greeting(message):
                return None
            rows = conn.execute(
                "SELECT id, normalized_question, question, answer FROM answer_dataset WHERE mode IN (?, 'New Chat') ORDER BY use_count DESC, created_at DESC LIMIT 600",
                (str(mode or "New Chat")[:80],),
            ).fetchall()
            best = None
            best_score = 0.0
            for item in rows:
                if not _is_casual_greeting(item[2]):
                    continue
                score = difflib.SequenceMatcher(None, normalized, item[1]).ratio()
                if score > best_score:
                    best_score, best = score, item
            if best and best_score >= 0.52:
                conn.execute("UPDATE answer_dataset SET use_count=use_count+1,last_used_at=CURRENT_TIMESTAMP WHERE id=?", (best[0],))
                return {"answer": best[3], "match": "similar", "question": best[2], "score": round(best_score, 3)}
    except Exception as exc:
        print("[Indo AI dataset lookup error]", repr(exc))
    return None


# ============================================================
# DATA MODELS
# ============================================================

class Attachment(BaseModel):
    filename: str
    url: str
    file_type: str
    data_b64: str | None = None
    extracted_text: str | None = None


class Message(BaseModel):
    role: str
    content: str
    attachments: list[Attachment] = Field(default_factory=list)
    id: str = ""
    reply_to: str = ""
    reply_context: str = ""


class ChatRequest(BaseModel):
    message: str
    selected_model: str = "MIRA 1"
    mode: str = "New Chat"
    custom_persona: str = ""
    answer_style: str = "aesthetic"
    history: list[Message] = Field(default_factory=list)
    # Client conversation ID is a boundary label only, never authentication.
    session_id: str = ""
    attachments: list[Attachment] = Field(default_factory=list)
    visual_answers: bool = True
    url_inspection: bool = True
    # Set only by the server from the signed-in user's private memory database.
    private_memory_context: str = ""
    # Optional explicit quoted-message context; never used as authentication.
    reply_to_id: str = ""
    reply_context: str = ""


# Developer-only usage monitor. Indo no longer imposes a per-account daily chat cap.
# Keep the legacy environment name readable for compatibility, but it is deliberately
# disabled: provider quotas/costs are handled by provider health and infrastructure policy.
INDO_DAILY_CHAT_LIMIT = 0
INDO_DEVELOPER_EMAIL = os.getenv("INDO_DEVELOPER_EMAIL", "").strip().lower()
INDO_DEVELOPER_USER_KEY = os.getenv("INDO_DEVELOPER_USER_KEY", "").strip().lower()
INDO_USAGE_DB = Path(os.getenv("INDO_USAGE_DB", str(INDO_DATA_DIR / "IndoUsage.sqlite3"))).expanduser()
_INDO_USAGE_DB_LOCK = threading.RLock()

def _indo_usage_db():
    conn = sqlite3.connect(str(INDO_USAGE_DB), timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout=10000")
    conn.execute("""CREATE TABLE IF NOT EXISTS daily_usage (
        day_utc TEXT NOT NULL, user_hash TEXT NOT NULL, email TEXT NOT NULL,
        request_count INTEGER NOT NULL DEFAULT 0, denied_count INTEGER NOT NULL DEFAULT 0,
        updated_at INTEGER NOT NULL, PRIMARY KEY(day_utc, user_hash)
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS usage_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT, day_utc TEXT NOT NULL,
        user_hash TEXT NOT NULL, email TEXT NOT NULL, event TEXT NOT NULL,
        provider TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL
    )""")
    conn.commit()
    return conn

def _indo_usage_identity(user: dict) -> tuple[str, str]:
    identity = str(user.get("user_key") or (str(user.get("provider") or "account") + ":" + str(user.get("email") or ""))).strip().lower()
    return hashlib.sha256(identity.encode("utf-8")).hexdigest()[:32], str(user.get("email") or "account").strip().lower()[:254]

def _indo_usage_reserve(user: dict) -> tuple[bool, int, int]:
    """Legacy-compatible telemetry recorder. It never denies a chat turn."""
    user_hash, email = _indo_usage_identity(user)
    day = _indo_datetime.datetime.now(_indo_datetime.timezone.utc).date().isoformat()
    now = int(time.time())
    with _INDO_USAGE_DB_LOCK:
        conn = _indo_usage_db()
        try:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute("SELECT request_count FROM daily_usage WHERE day_utc=? AND user_hash=?", (day, user_hash)).fetchone()
            used = int(row["request_count"]) if row else 0
            conn.execute("INSERT INTO daily_usage(day_utc,user_hash,email,request_count,denied_count,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(day_utc,user_hash) DO UPDATE SET email=excluded.email, request_count=daily_usage.request_count+1, updated_at=excluded.updated_at", (day,user_hash,email,1,0,now))
            conn.execute("INSERT INTO usage_events(day_utc,user_hash,email,event,provider,created_at) VALUES(?,?,?,?,?,?)", (day,user_hash,email,"chat_attempted", "", now))
            conn.commit()
            return True, used + 1, 0  # zero means unlimited; this value is never a quota.
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()

def _indo_usage_record_provider(user: dict | None, provider: str, event: str = "provider_attempt"):
    if not user:
        return
    user_hash, email = _indo_usage_identity(user)
    day = _indo_datetime.datetime.now(_indo_datetime.timezone.utc).date().isoformat()
    with _INDO_USAGE_DB_LOCK:
        conn = _indo_usage_db()
        try:
            conn.execute("INSERT INTO usage_events(day_utc,user_hash,email,event,provider,created_at) VALUES(?,?,?,?,?,?)", (day,user_hash,email,event,str(provider or "")[:40],int(time.time())))
            conn.commit()
        finally:
            conn.close()

def _indo_is_developer(user: dict | None) -> bool:
    if not user:
        return False
    email = str(user.get("email") or "").strip().lower()
    user_key = str(user.get("user_key") or "").strip().lower()
    return bool((INDO_DEVELOPER_EMAIL and hmac.compare_digest(email, INDO_DEVELOPER_EMAIL)) or
                (INDO_DEVELOPER_USER_KEY and hmac.compare_digest(user_key, INDO_DEVELOPER_USER_KEY)))

@app.get("/api/dev/usage")
def indo_developer_usage(request: Request):
    """Developer-only aggregate usage; no prompts, response content, or API secrets are stored."""
    user = _indo_current_user(request)
    if not _indo_is_developer(user):
        return JSONResponse({"error": "Not found."}, status_code=404)
    day = _indo_datetime.datetime.now(_indo_datetime.timezone.utc).date().isoformat()
    with _INDO_USAGE_DB_LOCK:
        conn = _indo_usage_db()
        try:
            rows = conn.execute("SELECT email, request_count, denied_count, updated_at FROM daily_usage WHERE day_utc=? ORDER BY request_count DESC LIMIT 200", (day,)).fetchall()
            events = conn.execute("SELECT event, provider, COUNT(*) AS count FROM usage_events WHERE day_utc=? GROUP BY event, provider ORDER BY count DESC", (day,)).fetchall()
            total = conn.execute("SELECT COALESCE(SUM(request_count),0) AS n, COALESCE(SUM(denied_count),0) AS d FROM daily_usage WHERE day_utc=?", (day,)).fetchone()
        finally:
            conn.close()
    return {"date_utc":day,"daily_account_limit":None,"daily_account_limit_enabled":False,"total_reserved_turns":int(total["n"]),"total_denied_turns":int(total["d"]),"accounts":[dict(r) for r in rows],"events":[dict(r) for r in events],"privacy":"No prompts, answers, API keys, or message content are stored.","usage_note":"Historical/operational counters only; Indo does not impose a per-account daily chat cap."}

@app.get("/dev/usage", response_class=HTMLResponse)
def indo_developer_usage_page(request: Request):
    if not _indo_is_developer(_indo_current_user(request)):
        return HTMLResponse("Not found", status_code=404)
