class TitleRequest(BaseModel):
    history: list[Message]


class URLRequest(BaseModel):
    url: str


class MusicDownloadRequest(BaseModel):
    url: str
    title: str = "Audio track"
    artist: str = "Unknown artist"


class ImageGenerationRequest(BaseModel):
    prompt: str
    aspect_ratio: str = "1:1"
    image_size: str = "1K"
    reference_image: str = ""
    reference_mime_type: str = "image/png"



class PDFGenerationRequest(BaseModel):
    title: str = "Indo AI Document"
    content: str


class PDFPrepareRequest(BaseModel):
    title: str = "Indo AI Document"
    user_prompt: str = ""
    answer: str = ""
    mode: str = "New Chat"
    preserve_source: bool = False


class FileGenerationRequest(BaseModel):
    title: str = "Indo AI File"
    content: str
    file_type: str = "txt"


class FilePrepareRequest(BaseModel):
    title: str = "Indo AI File"
    user_prompt: str = ""
    answer: str = ""
    mode: str = "New Chat"
    file_type: str = "txt"
    preserve_source: bool = False


class SearchRequest(BaseModel):
    query: str
    engine: str = "Google"


class SpeechRequest(BaseModel):
    text: str
    voice_id: str | None = None
    voice_style: str = "lovely"


class FeedbackRequest(BaseModel):
    rating: int
    reason: str = ""
    question: str = ""
    mode: str = "New Chat"


