# ============================================================
# SAFE URL SYSTEM
# ============================================================

def is_private_host(host):

    if not host:
        return True

    host = host.lower().strip()

    if host in (
        "localhost",
        "localhost.localdomain"
    ):
        return True

    try:
        addresses = socket.getaddrinfo(
            host,
            None
        )

        for item in addresses:

            ip = item[4][0]
            obj = ipaddress.ip_address(ip)

            if (
                obj.is_private
                or obj.is_loopback
                or obj.is_link_local
                or obj.is_reserved
                or obj.is_multicast
            ):
                return True

    except Exception:
        return True

    return False


def validate_public_url(url):

    try:

        parsed = urlparse(url)

        if parsed.scheme not in ("http", "https"):
            return False

        if not parsed.hostname:
            return False

        if is_private_host(parsed.hostname):
            return False

        return True

    except Exception:
        return False


def classify_url(url):

    parsed = urlparse(url)

    host = (parsed.hostname or "").lower()
    path = (parsed.path or "").lower()

    if (
        "youtube.com" in host
        or "youtu.be" in host
    ):
        return "youtube"

    if "vimeo.com" in host:
        return "vimeo"

    if path.endswith(
        (".jpg", ".jpeg", ".png", ".webp", ".gif")
    ):
        return "image"

    if path.endswith(
        (".mp4", ".webm", ".mov", ".ogg")
    ):
        return "video"

    return "webpage"


def safe_fetch_url(url):

    if not validate_public_url(url):
        raise ValueError("URL blocked for safety.")

    request = urllib.request.Request(
        url,
        headers={
            "User-Agent": "IndoAI-SafeInspector/1.0"
        }
    )

    with urllib.request.urlopen(
        request,
        timeout=8
    ) as response:

        final_url = response.geturl()

        if not validate_public_url(final_url):
            raise ValueError(
                "Redirect destination was blocked for safety."
            )

        content_type = response.headers.get(
            "Content-Type",
            ""
        )

        content_length = response.headers.get(
            "Content-Length"
        )

        if content_length:

            try:
                size = int(content_length)
            except Exception:
                size = None

            if size is not None and size > MAX_URL_BYTES:
                raise ValueError(
                    "Remote file is too large."
                )

        data = response.read(
            MAX_URL_BYTES + 1
        )

        if len(data) > MAX_URL_BYTES:
            raise ValueError(
                "Remote file is too large."
            )

        return data, content_type, final_url


def inspect_url(url):

    result = {
        "url": url,
        "kind": "unknown",
        "safe": False,
        "title": "",
        "description": "",
        "content_type": ""
    }

    if not validate_public_url(url):

        result["description"] = (
            "This URL was blocked because it did not "
            "pass the public URL safety checks."
        )

        return result

    kind = classify_url(url)

    result["kind"] = kind
    result["safe"] = True

    if kind == "image":

        try:

            data, content_type, final_url = safe_fetch_url(url)

            if not content_type.lower().startswith("image/"):

                result["safe"] = False
                result["description"] = (
                    "The URL did not return an image."
                )

                return result

            result["content_type"] = content_type
            result["description"] = (
                "A public image URL was safely fetched."
            )

            result["data_b64"] = base64.b64encode(
                data
            ).decode()

            result["final_url"] = final_url

        except Exception as e:

            result["description"] = (
                f"Image inspection failed: {e}"
            )

        return result

    if kind in ("youtube", "vimeo", "video"):

        result["description"] = (
            "This is a public video URL. Indo AI can "
            "identify the URL type but does not pretend "
            "to watch video content unless video data "
            "is actually available."
        )

        return result

    result["description"] = (
        "This is a public webpage URL. Indo AI does "
        "not execute arbitrary webpage JavaScript."
    )

    return result


