def _adaptive_thinking_level(req):
    """Choose fast, standard or deep execution using the local cognitive planner."""
    mode = str(getattr(req, "mode", "New Chat") or "New Chat").strip().casefold()
    message = str(getattr(req, "message", "") or "").strip()
    low = message.casefold()

    # Specialist modes and explicit technical/research work always receive the deep lane.
    if mode in {"research", "web research", "web", "coding", "code"}:
        return "deep"
    if getattr(req, "attachments", None) or find_urls(message):
        return "deep"
    if _is_current_affairs_query(message) or _is_song_research_query(message):
        return "deep"

    # v15 planner: an independent, explainable local signal for complex task routing.
    # It does not call a provider and never claims that a tool was executed.
    try:
        v15_plan = plan_intelligence(
            message, mode, len(getattr(req, "attachments", []) or []),
            len(getattr(req, "history", []) or [])
        )
        if v15_plan.get("lane") == "deep":
            return "deep"
    except Exception as planner_exc:
        print("[Indo v15 planner fallback]", type(planner_exc).__name__)

    # Use the same no-API local classifier as the Brain Engine. Technical architecture
    # prompts (e.g. designing an AI assistant around a frozen LLM) count as engineering.
    try:
        cognitive = analyze_request(message, mode, len(getattr(req, "attachments", []) or []))
        if cognitive.get("tier") == "deep" and cognitive.get("task") in {"coding", "research", "math_logic"}:
            return "deep"
    except Exception as planner_exc:
        print("[Indo cognitive planner fallback]", type(planner_exc).__name__)

    if getattr(req, "custom_persona", "").strip() and len(req.custom_persona) > 1800:
        return "standard"

    deep_phrases = (
        "step by step", "in depth", "deep dive", "comprehensive", "full implementation",
        "complete application", "entire code", "debug", "traceback", "stack trace",
        "architecture", "system design", "optimize this code", "security audit",
        "prove that", "formal proof", "derive the formula", "compare in detail",
        "analyze thoroughly", "research this", "multiple sources", "with citations",
        "make a complete plan", "multi-step", "find the bug", "fix this code",
        "write code", "build an app", "create a website", "api integration",
        "ai assistant", "large language model", "frozen llm", "memory architecture",
        "production-ready", "end-to-end", "entire project", "full project",
    )
    if any(term in low for term in deep_phrases):
        return "deep"
    if re.search(r"```|\b(?:python|javascript|typescript|html|css|sql|fastapi|traceback|exception|api key|llm|microservices|oauth|database)\b", low):
        return "deep"

    words = re.findall(r"\b[\w'-]+\b", message)
    question_marks = message.count("?")
    multi_task = len(re.findall(r"\b(?:and also|then|after that|additionally|first|secondly|finally)\b", low)) >= 2
    reasoning_signals = re.search(
        r"\b(?:evaluate|analyze|analyse|synthesize|design|implement|refactor|troubleshoot|calculate|solve|prove|derive|compare|contrast|plan|strategy|why does|how would|what would happen if)\b",
        low,
    )
    if len(words) > 100 or multi_task or (reasoning_signals and len(words) > 35) or question_marks >= 3:
        return "deep"
    if reasoning_signals:
        return "standard"
    if len(words) <= 45 and mode in {"new chat", "indo", "default", "assistant", "chill", "gaming", "creative", "study", ""}:
        return "fast"
    return "standard"

def _ultra_fast_eligible(req):
    """Route ordinary low-risk chat to the compact streaming path without expensive classification."""
    message = str(getattr(req, "message", "") or "").strip()
    low = message.casefold()
    mode = str(getattr(req, "mode", "New Chat") or "New Chat").strip().casefold()
    if not message or getattr(req, "attachments", None) or find_urls(message):
        return False
    if _adaptive_thinking_level(req) == "deep":
        return False
    if mode in {"research", "web research", "web", "coding"}:
        return False
    if _is_current_affairs_query(message) or _is_song_research_query(message):
        return False
    if _indo_should_auto_research(message, mode):
        return False
    if re.search(r"```|\b(?:traceback|stack trace|security audit|debug this|refactor|implement|architecture|system design|multiple sources|with citations|fact check|verify this|search the web|look up|browse)\b", low):
        return False
    if re.search(r"\b(?:message|msg|text|contact|call|dm|phone)\b", low):
        return False
    if any(term in low for term in (
        "latest", "today", "right now", "currently", "current price", "this week",
        "breaking news", "live score", "current score", "weather", "news", "stock price",
        "recent announcement", "sources", "citations", "search online", "browse the web",
    )):
        return False
    # Keep everyday questions, personal-context questions, and short explanations light.
    # Longer multi-part work and explicit research remain on the full-quality path.
    words = re.findall(r"\b[\w'-]+\b", message)
    if len(words) > 100 or message.count("?") > 3:
        return False
    if re.search(r"\b(?:complete application|entire code|full implementation|step by step|deep dive|comprehensive|prove that|derive the formula|analyze thoroughly|analyse thoroughly|build an app|create a website)\b", low):
        return False
    return True

def _guard_unfounded_contact_suggestions(req, answer):
    """Remove unsolicited message/call offers that name a person absent from user context."""
    answer = str(answer or "")
    if not answer.strip():
        return answer

    context_parts = [str(getattr(req, "message", "") or "")]
    for item in (getattr(req, "history", []) or [])[-12:]:
        # Only the user's own messages can ground a person's identity; never let
        # a previous assistant hallucination validate its own invented name.
        if str(getattr(item, "role", "") or "").casefold() == "user":
            context_parts.append(str(getattr(item, "content", "") or ""))
    user_context = " ".join(context_parts).casefold()

    # Only inspect sentences that look like an offer/question to contact someone.
    sentence_pattern = re.compile(r"[^.!?\n]*(?:[.!?]+|$)")
    sentences = sentence_pattern.findall(answer)
    cleaned = []
    changed = False
    offer_pattern = re.compile(
        r"\b(?:do you want|would you like|should i|want me to|shall i)\b"
        r"[^.!?\n]{0,100}\b(?:message|msg|text|contact|call|dm)\b"
        r"[^.!?\n]{0,70}", re.I
    )
    contact_target_pattern = re.compile(
        r"\b(?:message|msg|text|contact|call|dm)\s+"
        r"(?:(?:him|her|them|that person|your friend|your sister|your brother)\s+)?"
        r"([A-Za-z][A-Za-z'’-]{2,})\b", re.I
    )
    pronouns = {"him", "her", "them", "someone", "anyone", "me", "you", "us", "it", "that", "person", "friend", "sister", "brother"}
    for sentence in sentences:
        if not sentence:
            continue
        if offer_pattern.search(sentence):
            target_match = contact_target_pattern.search(sentence)
            if target_match:
                target = target_match.group(1).strip("'’- ")
                if target.casefold() not in pronouns and target.casefold() not in user_context:
                    changed = True
                    continue
        cleaned.append(sentence)

    result = "".join(cleaned).strip()
    if changed and not result:
        return "I shouldn't assume who you know or suggest contacting someone you haven't mentioned. If you want help with a message, tell me who it's for and I'll help draft it."
    if changed:
        result += "\n\nI removed an unsupported suggestion about a person you hadn't mentioned."
    return result


def _build_ultra_fast_prompt(req):
    """Compact prompt for conversational turns, with separate voice/text output styles."""
    mode = str(getattr(req, "mode", "New Chat") or "New Chat").strip()
    selected_model = str(getattr(req, "selected_model", "MIRA 1") or "MIRA 1").strip().upper()
    selected_model = "VISHNU 1" if selected_model == "VISHNU 1" else "MIRA 1"
    style = str(getattr(req, "answer_style", "aesthetic") or "aesthetic").strip().lower()
    raw_message = str(getattr(req, "message", "") or "").strip()
    voice_match = re.search(r"\s*\[VOICE CHAT STYLE:.*?\]\s*$", raw_message, flags=re.I | re.S)
    is_voice_chat = bool(voice_match)
    user_message = raw_message[:voice_match.start()].strip() if voice_match else raw_message
    style_rule = (
        "Use polished, respectful, professional language."
        if style == "official" else
        "Match the user's tone naturally; casual Hinglish is welcome when the user uses it. Be warm, direct, and not robotic."
    )
    format_rule = (
        "VOICE OUTPUT FOR THIS TURN ONLY: Answer in 1–3 natural spoken sentences by default. Do not read Markdown syntax, headings, bullets, or emoji names aloud. Keep the response concise unless the user asks for detail. This voice-only style must not affect future text-chat answers."
        if is_voice_chat else
        "TEXT OUTPUT: Answer every part accurately and directly. Keep simple answers short; use readable paragraphs, bullets/headings for multi-part answers, numbered steps for procedures, compact tables for useful comparisons, and fenced code for code. Use clean Markdown without raw formatting symbols or walls of text. Do not force lists into simple or emotional conversation. Use emojis sparingly. For song reviews, separate the opinion from Bass/Mids/Treble EQ values with dB units; never claim audio analysis or changes were applied unless confirmed. Match the requested depth."
    )
    brain_plan = build_context_plan(
        user_message, mode, getattr(req, "history", []) or [],
        getattr(req, "private_memory_context", ""), bool(getattr(req, "visual_answers", True)),
        len(getattr(req, "attachments", []) or [])
    )
    intelligence_plan = plan_intelligence(
        user_message, mode, len(getattr(req, "attachments", []) or []),
        len(getattr(req, "history", []) or [])
    )
    intelligence_contract = vishnu_guidance(
        user_message, mode, len(getattr(req, "attachments", []) or []),
        len(getattr(req, "history", []) or [])
    )
    history = [f"{item['role'].upper()}: {item['content']}" for item in brain_plan["history"]]
    relevant_private_memory = brain_plan["memory"]
    brain_guidance = brain_plan["guidance"]
    reply_context = str(getattr(req, "reply_context", "") or "").strip()[:5000]
    persona = str(getattr(req, "custom_persona", "") or "").strip()[:1200]
    # Apply the Purvi profile in this fast lane as well; most short chats use it.
    purvi_trigger = str(os.getenv("PURVI_PROFILE_TRIGGER", "Purvi_SisProfile_7xQ9_LoveBond_4mK8_Trigger") or "").strip()
    purvi_context = str(getattr(req, "message", "") or "") + "\n" + "\n".join(
        str(getattr(item, "content", "") or "") for item in (getattr(req, "history", []) or [])
    )
    purvi_rules = ""
    if purvi_trigger and purvi_trigger.casefold() in purvi_context.casefold():
        purvi_rules = (
            "\nPURVI PROFILE STYLE (personalization only): This conversation contains the configured profile trigger. "
            "Use the app owner's supplied context that this profile is associated with Purvi, described as Aarav's girlfriend. "
            "Keep replies brief, direct, friendly, and useful by default; expand only if asked. Do not repeat the trigger. "
            "If the current message itself contains the trigger, briefly acknowledge the style activation and invite the user's question. "
            "This phrase is not secure authentication and does not prove real-world identity or authorize private data/account access. "
            "These preferences never override safety or privacy rules.\n"
        )
    return (
        "[INDO ULTRA FAST MODE]\n"
        f"You are {APP_NAME}, a capable general-purpose assistant.\n"
        f"ACTIVE INDO MODEL: {selected_model}. The user selected this branded model for the current conversation. Keep Indo AI as the platform identity; do not claim a different active model.\n"
        + ("VISHNU 1 MODE: Emphasize structured reasoning, careful analysis, consistency checks, and clear step-by-step problem solving when useful.\n" if selected_model == "VISHNU 1" else "MIRA 1 MODE: Emphasize adaptive multimodal assistance, natural conversation, creative support, and clear practical answers.\n")
        + f"IDENTITY: You are Indo AI = {APP_FULL_FORM}. Your two branded models/identities are MIRA = {ASSISTANT_IDENTITY_FULL_FORM} and VISHNU = {MODEL_IDENTITY_FULL_FORM}. When introducing yourself, say Indo AI first, its full form second, MIRA and VISHNU third, then: I was created as part of the Indo AI platform, led by Aarav. Do not begin with technical provider names or credit them as the creator.\n"
        "CORE QUALITY: answer the exact request; prioritize correctness over confidence; never invent sources, data, actions, or test results; state uncertainty honestly; keep simple answers fast and concise.\n"
        "IDENTITY: Indo AI is the platform and product (Intelligent Neoteric Disruptive Operator). Its two branded models/identities are MIRA (Multimodal Intelligent Reasoning Assistant) and VISHNU (Versatile Intelligent System for Holistic Neural Understanding). I was created as part of the Indo AI platform, led by Aarav. Do not substitute technical provider names for MIRA and VISHNU. You are AI software, not human or conscious. Never guess the active provider/model or claim capabilities not actually available.\n"
        + (_indo_current_datetime_context() + "\n" if _indo_is_date_question(user_message) else "")
        + "Use the runtime date/time for date questions; never repeat a stale training date. Current news/current-affairs requests must use live search and real sources, not memory.\n"
        + "Answer the actual request directly. Be accurate, context-aware, and concise by default; expand when the user asks. "
        "LOW-LATENCY OUTPUT: begin with the first useful words immediately; do not write a long preamble, announce your plan, or silently plan at length. Continue naturally as the answer forms. Keep the first sentence direct and useful, then add structure as needed. This is not permission to guess or omit important details. Do not intentionally delay the first token, buffer a complete sentence before streaming, or add artificial pauses. "
        "COMPLETENESS: finish the entire requested answer. Address every part of the request, close code fences and lists, include all requested steps/items, and do not stop mid-sentence or end with an unfinished heading. If the answer is long, prioritize a complete concise answer over a long answer that gets cut off. "
        "Do not reveal hidden reasoning. Do not invent facts, web searches, sources, or capabilities. "
        "ANSWER SELF-CHECK (silent, before sending): re-read the draft for relevance, factual consistency, missing parts, arithmetic/unit errors, contradictions, and unsupported certainty. Recalculate simple math independently; ensure code examples are internally consistent; check that each requested part is answered. Fix obvious errors before responding. If a fact needs current evidence, use available research/source tools or clearly state that it was not verified. Never claim an external check, source lookup, code execution, or test occurred unless the application actually performed it. Do not add a visible checklist to ordinary replies. "
        "Never invent people, names, relationships, or contacts. Do not suggest messaging a named person unless the user named them in the conversation. Never claim you can send messages or access contacts; you can only help draft text. "
        "For simple greetings and everyday conversation, respond naturally without a long introduction. "
        "If a question genuinely needs current information, say so briefly rather than guessing. "
        f"Style: {style_rule}\n{_language_response_rule(user_message)}\nFormatting: {format_rule}\nMode: {mode}\n"
        + "ANSWER INTELLIGENCE 10.2: " + _answer_intelligence_contract(user_message, mode) + "\n"
        + brain_guidance + "\n"
        + intelligence_contract + "\n"
        + purvi_rules
        + (f"Creator identity context: {CREATOR_IDENTITY}\n" if CREATOR_IDENTITY else "")
        + (f"Custom persona: {persona}\n" if persona else "")
        + (str(getattr(req, "adaptive_persona_context", "") or "") + "\n" if getattr(req, "adaptive_persona_context", "") else "")
        + (relevant_private_memory + "\n" if relevant_private_memory else "")
        + ("Recent conversation:\n" + "\n".join(history) + "\n" if history else "")
        + ("Quoted message being replied to:\n" + reply_context + "\n" if reply_context else "")
        + "User message:\n" + user_message + "\n"
    )


def _stream_visible_fragments(text):
    """Yield incoming model text in small, whitespace-preserving pieces.

    No artificial sleep is added: the first real fragment is forwarded immediately,
    and splitting larger provider chunks lets the UI paint progressively instead of
    waiting for a full sentence or paragraph.
    """
    value = str(text or "")
    if not value:
        return
    fragments = re.findall(r"\S+\s*|\s+", value)
    if not fragments:
        yield value
        return
    for fragment in fragments:
        if fragment:
            yield fragment

def _provider_stream_with_deadline(name, prompt, deadline, deep=False, attachments=None):
    """Consume a synchronous provider stream with a strict wall-clock deadline.

    A daemon worker prevents a stalled SDK iterator from blocking the request
    thread beyond its budget. Provider socket timeouts are configured separately.
    """
    events = queue.Queue()

    def _run():
        try:
            for _chunk in _provider_stream(name, prompt, deep=deep, attachments=attachments):
                events.put(("chunk", _chunk))
            events.put(("done", None))
        except BaseException as _exc:
            events.put(("error", _exc))

    threading.Thread(target=_run, name=f"indo-{name}-ultrafast", daemon=True).start()
    first_chunk_received = False
    while True:
        # The 4-second budget is for the first token, not the entire answer.
        # Once streaming begins, allow the provider to finish normally.
        if not first_chunk_received:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise TimeoutError(f"{name} exceeded its ultra-fast first-token deadline")
            wait_for = remaining
        else:
            wait_for = max(30.0, PROVIDER_TIMEOUT)
        try:
            kind, payload = events.get(timeout=wait_for)
        except queue.Empty:
            if not first_chunk_received:
                raise TimeoutError(f"{name} exceeded its ultra-fast first-token deadline")
            raise TimeoutError(f"{name} stream stalled after its first token")
        if kind == "chunk":
            if payload:
                first_chunk_received = True
                yield payload
        elif kind == "error":
            raise payload
        else:
            return


def _collect_optional_provider_fallback(configured, primary_names, prompt, deep=False, attachments=None):
    """Try configured non-primary providers (for example a self-hosted Ollama model).

    This path is used only after the hosted-provider race fails before emitting text.
    It deliberately does not rotate accounts, keys, or identities to evade quotas.
    """
    if attachments:
        return None, ""
    for provider_name in configured:
        if provider_name in primary_names:
            continue
        try:
            chunks = [str(part) for part in _provider_stream(provider_name, prompt, deep=deep, attachments=None) if part]
            answer = "".join(chunks).strip()
            if answer:
                print(f"[Indo AI fallback] served by optional provider: {provider_name}")
                return provider_name, answer
        except Exception as fallback_exc:
            print(f"[Indo AI optional fallback failure] {provider_name}: {type(fallback_exc).__name__}: {str(fallback_exc)[:180]}")
    return None, ""


def stream_response(req):
    configured = _ordered_configured_providers()
    # Ollama is text-only in this adapter; do not route image/file attachments to it.
    if getattr(req, "attachments", None):
        configured = [name for name in configured if name != "ollama"]
    failures = []

    # Direct date/time questions use the runtime clock, not model training data.
    if _indo_is_date_question(getattr(req, "message", "")) and "[VOICE CHAT STYLE:" not in str(getattr(req, "message", "")):
        try:
            from zoneinfo import ZoneInfo
            now = _indo_datetime.datetime.now(ZoneInfo("Asia/Kolkata"))
            date_answer = f"Today is **{now.strftime('%A, %d %B %Y')}** (India Standard Time)."
        except Exception:
            now = _indo_datetime.datetime.now().astimezone()
            date_answer = f"Today is **{now.strftime('%A, %d %B %Y')}** ({now.tzname() or 'local time'})."
        yield _source_marker([])
        yield date_answer
        return

    # Ultra-fast parallel race: start every configured text provider together. The first
    # provider to produce a non-empty text chunk wins; its stream is forwarded
    # immediately and losing workers are asked to stop. The race uses a shared
    # first-token deadline to keep perceived latency bounded.
    if _ultra_fast_eligible(req):
        prompt = _build_ultra_fast_prompt(req)
        yield _source_marker([])
        race_events = queue.Queue()
        provider_cancel = {"gemini": threading.Event(), "openai": threading.Event(), "ollama": threading.Event()}
        race_providers = [p for p in ("gemini", "openai", "ollama") if p in configured]
        race_timeout = OLLAMA_FIRST_TOKEN_TIMEOUT if race_providers == ["ollama"] else INDO_ULTRA_FAST_TOTAL_TIMEOUT
        race_deadline = time.monotonic() + race_timeout
        failures = []

        def _race_provider_worker(provider_name):
            stream = None
            try:
                stream = _provider_stream(provider_name, prompt, deep=False, attachments=None)
                for part in stream:
                    if provider_cancel[provider_name].is_set():
                        break
                    if part:
                        race_events.put(("chunk", provider_name, str(part)))
                race_events.put(("done", provider_name, None))
            except BaseException as worker_exc:
                race_events.put(("error", provider_name, worker_exc))
            finally:
                if stream is not None:
                    try:
                        stream.close()
                    except Exception:
                        pass

        if not race_providers:
            fallback_name, fallback_answer = _collect_optional_provider_fallback(
                configured, {"gemini", "openai", "ollama"}, prompt, deep=False, attachments=req.attachments
            )
            if fallback_answer:
                for fragment in _stream_visible_fragments(fallback_answer):
                    yield fragment
                if not req.history and not req.custom_persona.strip():
                    _dataset_save_async(req.message, fallback_answer, req.mode)
                return
            yield "No healthy text provider is currently available. Indo's daily chat cap is disabled; check provider configuration or enable a self-hosted fallback if you have one."
            return

        for provider_name in race_providers:
            threading.Thread(
                target=_race_provider_worker,
                args=(provider_name,),
                name=f"indo-{provider_name}-parallel-race",
                daemon=True,
            ).start()

        winner = None
        first_piece = None
        completed = set()
        # Wait for the first valid text chunk, while allowing either provider
        # to fail independently without blocking the other.
        while winner is None and len(completed) < len(race_providers):
            remaining = race_deadline - time.monotonic()
            if remaining <= 0:
                failures.append("All configured providers exceeded the shared first-token deadline")
                break
            try:
                event, provider_name, payload = race_events.get(timeout=remaining)
            except queue.Empty:
                failures.append("All configured providers exceeded the shared first-token deadline")
                break
            if event == "chunk" and payload and payload.strip():
                winner = provider_name
                first_piece = payload
                break
            if event == "error":
                failures.append(_provider_error_text(provider_name, payload))
                print(f"[Indo AI parallel provider failure] {provider_name}: {repr(payload)}")
                completed.add(provider_name)
            elif event == "done":
                completed.add(provider_name)
                failures.append(f"{provider_name.title()} returned an empty response")

        if winner is not None:
            # Signal cancellation to the losing worker. If its HTTP iterator is
            # currently blocked inside the SDK, the daemon worker exits when the
            # next chunk arrives or its configured network read timeout expires.
            for provider_name in race_providers:
                if provider_name != winner:
                    provider_cancel[provider_name].set()
            collected = [first_piece]
            emitted_any = True
            for visible_fragment in _stream_visible_fragments(first_piece):
                yield visible_fragment

            winner_done = False
            while not winner_done:
                try:
                    event, provider_name, payload = race_events.get(timeout=max(OLLAMA_PROVIDER_TIMEOUT if winner == "ollama" else 30.0, PROVIDER_TIMEOUT))
                except queue.Empty:
                    yield "\n\n⚠️ The response stream stalled after starting. The answer may be incomplete; please retry."
                    return
                if provider_name != winner:
                    # Ignore late chunks/errors from the losing provider.
                    continue
                if event == "chunk" and payload:
                    collected.append(payload)
                    for visible_fragment in _stream_visible_fragments(payload):
                        yield visible_fragment
                elif event == "error":
                    print(f"[Indo AI parallel winner stream failure] {winner}: {repr(payload)}")
                    yield "\n\n⚠️ The provider interrupted generation or reached its output limit after automatic continuation. The answer may be incomplete; please ask Mira to continue."
                    return
                elif event == "done":
                    winner_done = True

            answer = "".join(collected).strip()
            if answer and not req.history and not req.custom_persona.strip():
                try:
                    _dataset_save_async(req.message, answer, req.mode)
                except Exception:
                    pass
            return

        if failures:
            fallback_name, fallback_answer = _collect_optional_provider_fallback(
                configured, {"gemini", "openai", "ollama"}, prompt, deep=False, attachments=req.attachments
            )
            if fallback_answer:
                for fragment in _stream_visible_fragments(fallback_answer):
                    yield fragment
                if not req.history and not req.custom_persona.strip():
                    _dataset_save_async(req.message, fallback_answer, req.mode)
                return
            reason = "; ".join(dict.fromkeys(failures))[:500]
            cached = None
            if not req.history and not req.attachments and not req.custom_persona.strip():
                cached = _dataset_lookup(req.message, req.mode, allow_similar=True)
            if cached:
                print(f"[Indo AI parallel-race cache fallback] {cached.get('match')} match for: {req.message[:100]!r}")
                yield _guard_unfounded_contact_suggestions(req, cached["answer"])
            else:
                yield ("Both AI providers are temporarily unavailable or failed to respond within 12 seconds. "
                       "Check provider status and API credits, then retry. Your message is still here.")
            return


    # Direct first-token streaming for ordinary questions across modes.
    # The former normal path buffered the provider's entire first draft before sending
    # anything to the browser. This path forwards small fragments as soon as the
    # provider yields them. Explicit research/current-affairs requests retain the
    # evidence-first pipeline; contact-suggestion turns remain buffered for guarding.
    requested_mode = str(getattr(req, "mode", "") or "").strip().lower()
    current_affairs_for_stream = _is_current_affairs_query(getattr(req, "message", ""))
    forced_research_for_stream = (
        requested_mode in {"research", "web research", "web"}
        or (AUTO_WEB_SEARCH and current_affairs_for_stream)
        or (AUTO_WEB_SEARCH and _is_song_research_query(getattr(req, "message", "")))
        or _indo_should_auto_research(getattr(req, "message", ""), requested_mode)
    )
    contact_guard_for_stream = bool(re.search(
        r"\b(?:message|msg|text|contact|call|dm|phone)\b",
        str(getattr(req, "message", "") or ""), re.I
    ))
    if not forced_research_for_stream and not contact_guard_for_stream:
        initial_prompt = build_prompt(req, web_results=None, research_mode=False)
        yield _source_marker([])
        stream_failures = []
        # Deep tasks do NOT race both vendors: they get a longer single-provider
        # execution window and only fall back before any output is emitted. This
        # avoids duplicate provider charges and prevents the 12-second quick lane
        # from truncating architecture, debugging and full-code requests.
        deep_execution = _adaptive_thinking_level(req) == "deep"
        if deep_execution:
            for provider in configured:
                emitted = False
                pieces = []
                try:
                    for chunk in _provider_stream(provider, initial_prompt, deep=True, attachments=req.attachments):
                        if chunk:
                            piece = str(chunk)
                            emitted = True
                            pieces.append(piece)
                            for visible_fragment in _stream_visible_fragments(piece):
                                yield visible_fragment
                    if emitted:
                        complete_answer = "".join(pieces).strip()
                        if complete_answer and not req.history and not req.attachments and not req.custom_persona.strip():
                            try:
                                _dataset_save_async(req.message, complete_answer, req.mode)
                            except Exception:
                                pass
                        return
                    stream_failures.append(f"{provider.title()} returned an empty response")
                except Exception as exc:
                    stream_failures.append(_provider_error_text(provider, exc))
                    print(f"[Indo AI deep provider failure] {provider}: {repr(exc)}")
                    # Do not splice a second model into an answer already shown to the user.
                    if emitted:
                        yield "\n\n⚠️ The provider interrupted generation or reached its output limit after automatic continuation. The answer may be incomplete; please ask Mira to continue."
                        return
            if stream_failures:
                yield "I'm having trouble completing this complex request right now. The provider may be busy or its API limit may have been reached. Your message is still here; please retry."
            else:
                yield ("No text model is currently available. Configure valid Gemini, OpenAI, or Ollama Cloud credentials; "
                       "Ollama Cloud does not require a local installation or model download.")
            return

        # Short and standard requests retain the low-latency parallel race.
        # Attachment requests retain the established sequential route because
        # provider attachment capabilities differ.
        if not req.attachments:
            race_events = queue.Queue()
            provider_cancel = {"gemini": threading.Event(), "openai": threading.Event(), "ollama": threading.Event()}
            race_providers = [p for p in ("gemini", "openai", "ollama") if p in configured]
            race_timeout = OLLAMA_FIRST_TOKEN_TIMEOUT if race_providers == ["ollama"] else INDO_ULTRA_FAST_TOTAL_TIMEOUT
            race_deadline = time.monotonic() + race_timeout
            race_deep = _adaptive_thinking_level(req) == "deep"

            def _direct_race_worker(provider_name):
                stream = None
                try:
                    stream = _provider_stream(provider_name, initial_prompt, deep=race_deep, attachments=None)
                    for part in stream:
                        if provider_cancel[provider_name].is_set():
                            break
                        if part:
                            race_events.put(("chunk", provider_name, str(part)))
                    race_events.put(("done", provider_name, None))
                except BaseException as worker_exc:
                    race_events.put(("error", provider_name, worker_exc))
                finally:
                    if stream is not None:
                        try:
                            stream.close()
                        except Exception:
                            pass

            for provider_name in race_providers:
                threading.Thread(
                    target=_direct_race_worker,
                    args=(provider_name,),
                    name=f"indo-{provider_name}-direct-race",
                    daemon=True,
                ).start()

            winner = None
            first_piece = None
            completed = set()
            while winner is None and len(completed) < len(race_providers):
                remaining = race_deadline - time.monotonic()
                if remaining <= 0:
                    stream_failures.append("All configured providers exceeded the shared first-token deadline")
                    break
                try:
                    event, provider_name, payload = race_events.get(timeout=remaining)
                except queue.Empty:
                    stream_failures.append("All configured providers exceeded the shared first-token deadline")
                    break
                if event == "chunk" and payload and payload.strip():
                    winner, first_piece = provider_name, payload
                    break
                if event == "error":
                    stream_failures.append(_provider_error_text(provider_name, payload))
                    print(f"[Indo AI direct parallel provider failure] {provider_name}: {repr(payload)}")
                    completed.add(provider_name)
                elif event == "done":
                    completed.add(provider_name)
                    stream_failures.append(f"{provider_name.title()} returned an empty response")

            if winner:
                for provider_name in race_providers:
                    if provider_name != winner:
                        provider_cancel[provider_name].set()
                pieces = [first_piece]
                for visible_fragment in _stream_visible_fragments(first_piece):
                    yield visible_fragment
                winner_done = False
                while not winner_done:
                    try:
                        event, provider_name, payload = race_events.get(timeout=max(OLLAMA_PROVIDER_TIMEOUT if winner == "ollama" else 30.0, PROVIDER_TIMEOUT))
                    except queue.Empty:
                        yield "\n\n⚠️ The response stream stalled after starting. The answer may be incomplete; please retry."
                        return
                    if provider_name != winner:
                        continue
                    if event == "chunk" and payload:
                        pieces.append(payload)
                        for visible_fragment in _stream_visible_fragments(payload):
                            yield visible_fragment
                    elif event == "error":
                        print(f"[Indo AI direct parallel winner failure] {winner}: {repr(payload)}")
                        yield "\n\n⚠️ The provider interrupted generation or reached its output limit after automatic continuation. The answer may be incomplete; please ask Mira to continue."
                        return
                    elif event == "done":
                        winner_done = True
                complete_answer = "".join(pieces).strip()
                if complete_answer and not req.history and not req.attachments and not req.custom_persona.strip():
                    try:
                        _dataset_save_async(req.message, complete_answer, req.mode)
                    except Exception:
                        pass
                return

            fallback_name, fallback_answer = _collect_optional_provider_fallback(
                configured, {"gemini", "openai", "ollama"}, initial_prompt,
                deep=race_deep, attachments=req.attachments
            )
            if fallback_answer:
                for visible_fragment in _stream_visible_fragments(fallback_answer):
                    yield visible_fragment
                if not req.history and not req.attachments and not req.custom_persona.strip():
                    _dataset_save_async(req.message, fallback_answer, req.mode)
                return
            if stream_failures:
                yield ("Cloud AI providers are temporarily unavailable. Indo's daily chat cap is disabled, "
                       "but a provider or compute service must be available to generate an answer. "
                       "Enable a configured self-hosted fallback or retry after the provider recovers. Your message remains in this conversation.")
            else:
                yield ("No text model is currently available. Configure a Gemini API key, an OpenAI API key, or OLLAMA_API_KEY for Ollama Cloud. "
                       "Ollama Cloud runs remotely and does not require installing Ollama or downloading a model.")
            return

        # Requests with attachments keep the existing provider-specific route.
        for provider in configured:
            emitted = False
            pieces = []
            try:
                for chunk in _provider_stream(
                    provider, initial_prompt,
                    deep=_adaptive_thinking_level(req) == "deep",
                    attachments=req.attachments,
                ):
                    if chunk:
                        piece = str(chunk)
                        emitted = True
                        pieces.append(piece)
                        for visible_fragment in _stream_visible_fragments(piece):
                            yield visible_fragment
                if emitted:
                    complete_answer = "".join(pieces).strip()
                    if complete_answer and not req.history and not req.attachments and not req.custom_persona.strip():
                        try:
                            _dataset_save_async(req.message, complete_answer, req.mode)
                        except Exception:
                            pass
                    return
                stream_failures.append(f"{provider.title()} returned an empty response")
            except Exception as exc:
                stream_failures.append(_provider_error_text(provider, exc))
                print(f"[Indo AI direct-stream provider failure] {provider}: {repr(exc)}")
                if emitted:
                    yield "\n\n⚠️ The provider interrupted generation or reached its output limit after automatic continuation. The answer may be incomplete; please ask Mira to continue."
                    return
        if stream_failures:
            yield ("I'm experiencing high demand or a temporary connection issue right now. "
                   "Please try again in a little while; your message is still here.")
        else:
            yield "Indo is not ready to respond yet because no text provider is configured."
        return

    initial_prompt = build_prompt(req, web_results=None, research_mode=False)

    # Critical latency fix: voice chat streams tokens directly to the browser.
    # The normal path buffers an answer to decide whether web research is needed;
    # that means the browser receives nothing until generation is finished.
    # Voice replies are deliberately concise and should answer immediately without
    # waiting for background web research. Send the source header first so the UI
    # can safely render and speak the first complete sentence as it arrives.
    is_voice_chat = "[VOICE CHAT STYLE:" in str(getattr(req, "message", ""))
    if is_voice_chat:
        yield _source_marker([])
        voice_guard_context = str(getattr(req, "message", "") or "") + " " + " ".join(
            str(getattr(item, "content", "") or "") for item in (getattr(req, "history", []) or [])[-8:]
            if str(getattr(item, "role", "") or "").casefold() == "user"
        )
        buffer_voice_for_guard = bool(re.search(r"\b(?:message|msg|text|contact|call|dm|phone)\b", voice_guard_context, re.I))
        for provider in configured:
            emitted = False
            voice_chunks = []
            try:
                for chunk in _provider_stream(provider, initial_prompt, deep=False, attachments=req.attachments):
                    if chunk:
                        piece = str(chunk)
                        emitted = True
                        voice_chunks.append(piece)
                        # Buffer personal-contact requests so the contact guard can
                        # review the complete answer; otherwise stream for lower latency.
                        if not buffer_voice_for_guard:
                            for visible_fragment in _stream_visible_fragments(piece):
                                yield visible_fragment
                if emitted:
                    voice_answer = "".join(voice_chunks).strip()
                    if buffer_voice_for_guard:
                        voice_answer = _guard_unfounded_contact_suggestions(req, voice_answer)
                        if voice_answer:
                            yield voice_answer
                    if voice_answer and not req.history and not req.attachments and not req.custom_persona.strip():
                        try:
                            _dataset_save_async(req.message, voice_answer, req.mode)
                        except Exception:
                            pass
                    return
                failures.append(f"{provider.title()} returned an empty response")
            except Exception as exc:
                failures.append(_provider_error_text(provider, exc))
                print(f"[Indo AI voice provider failure] {provider}: {repr(exc)}")
                # A fallback is safe only before any text was sent to the browser.
                if emitted:
                    return
        if failures:
            yield "I'm experiencing high demand or a temporary connection issue right now. Please try again in a little while; your message is still here."
        else:
            yield "Indo is not ready to respond yet because its service setup needs attention. Please try again later."
        return

    # For explicit research, launch web retrieval BEFORE the first model call so
    # Gemini/fallback generation and the search/read pipeline overlap instead of
    # running one after the other. For eligible requests, stream the quick answer
    # immediately; the evidence-based result is appended as a clearly marked update.
    parallel_research_done = None
    parallel_research_box = {"results": []}
    parallel_research_thread = None
    initial_answer_streamed = False
    stream_quick_research_answer = bool(forced_research_for_stream and not contact_guard_for_stream)
    if forced_research_for_stream:
        parallel_research_done = threading.Event()
        def _parallel_research_worker():
            try:
                parallel_research_box["results"] = _perform_web_research(req)
            except Exception as exc:
                print(f"[Indo AI parallel research failure] {type(exc).__name__}: {exc}")
                parallel_research_box["results"] = []
            finally:
                parallel_research_done.set()
        parallel_research_thread = threading.Thread(target=_parallel_research_worker, daemon=True)
        parallel_research_thread.start()

    initial_answer = ""
    if stream_quick_research_answer:
        yield _source_marker([])
    for provider in configured:
        provider_chunks = []
        emitted_from_provider = False
        try:
            for chunk in _provider_stream(provider, initial_prompt, deep=(str(getattr(req, "mode", "") or "").strip().lower() in {"coding", "research", "web research", "web"} and not stream_quick_research_answer), attachments=req.attachments):
                if chunk:
                    piece = str(chunk)
                    provider_chunks.append(piece)
                    emitted_from_provider = True
                    if stream_quick_research_answer:
                        initial_answer_streamed = True
                        for visible_fragment in _stream_visible_fragments(piece):
                            yield visible_fragment
            candidate_answer = "".join(provider_chunks).strip()
            if candidate_answer:
                initial_answer = candidate_answer
                break
            failures.append(f"{provider.title()} returned an empty response")
        except Exception as exc:
            failures.append(_provider_error_text(provider, exc))
            print(f"[Indo AI provider failure] {provider}: {repr(exc)}")
            # Never splice another provider's words into an already-streamed draft.
            if stream_quick_research_answer and emitted_from_provider:
                break
    initial_answer = _guard_unfounded_contact_suggestions(req, initial_answer.strip())
    current_affairs_request = _is_current_affairs_query(getattr(req, "message", ""))
    current_affairs_quiz_request = _is_current_affairs_quiz_query(getattr(req, "message", ""))
    force_web = (
        str(getattr(req, "mode", "") or "").strip().lower() in {"research", "web research", "web"}
        or (AUTO_WEB_SEARCH and current_affairs_request)
        or (AUTO_WEB_SEARCH and _is_song_research_query(getattr(req, "message", "")))
        or _indo_should_auto_research(getattr(req, "message", ""), getattr(req, "mode", "New Chat"))
    )

    # Only use cached answers after configured providers failed, not instead of the primary provider.
    # Context-dependent chats/files/personas are never answered from the shared Q&A cache.
    if not initial_answer and not req.history and not req.attachments and not req.custom_persona.strip() and not force_web:
        cached = _dataset_lookup(req.message, req.mode, allow_similar=True)
        if cached:
            print(f"[Indo AI dataset fallback] {cached.get('match')} match for: {req.message[:100]!r}")
            yield cached["answer"]
            return

    if initial_answer and not force_web and not _answer_needs_web(req, initial_answer):
        if _should_review_code(req, initial_answer):
            initial_answer = _review_code_answer(req, initial_answer, configured)
        clean_answer = _strip_web_decision(initial_answer)
        # Save the successful answer for future fallback. The dataset is local to this installation.
        if not req.history and not req.attachments and not req.custom_persona.strip():
            _dataset_save_async(req.message, clean_answer, req.mode)
        yield clean_answer
        return

    # Reuse the parallel research job if it was started before model generation.
    # Otherwise run the existing research worker for adaptive web-needed answers.
    if parallel_research_done is not None:
        while not parallel_research_done.is_set():
            parallel_research_done.wait(0.03)
        results = parallel_research_box.get("results") or []
    else:
        research_status_queue, lock, done = [], threading.Lock(), threading.Event()
        box = {"results": []}
        def mark(name):
            with lock:
                research_status_queue.append(name)
        def worker():
            try:
                box["results"] = _perform_web_research(req, status_callback=mark)
            except Exception as exc:
                print(f"[Indo AI research worker failure] {type(exc).__name__}: {exc}")
                box["results"] = []
            finally:
                done.set()
        threading.Thread(target=worker, daemon=True).start()
        while not done.is_set() or research_status_queue:
            name = None
            with lock:
                if research_status_queue:
                    name = research_status_queue.pop(0)
            if name:
                yield WEB_STATUS_MARKER + name + WEB_STATUS_END
            else:
                done.wait(0.03)
        results = box["results"] or []
    if results:
        if current_affairs_request and not current_affairs_quiz_request:
            direct_news = _format_current_affairs_headlines(results, limit=7)
            if direct_news:
                yield _source_marker(results)
                if initial_answer_streamed:
                    yield "\n\n---\n\n## Verified research update\n\n"
                yield direct_news
                return
        yield WEB_STATUS_MARKER + "Building answer" + WEB_STATUS_END
        prompt = build_prompt(req, web_results=results, research_mode=True)
        prompt += "\n\nRESEARCH PASS: Use the searched/read evidence above. Cite important claims with [1], [2], etc. matching the supplied sources. Do not invent citations, URLs, or facts."
        if current_affairs_quiz_request:
            prompt += (
                "\nCURRENT-AFFAIRS QUIZ / EXAM REVISION RULES: Build the quiz only from the retrieved news items and their source details below. "
                "Create 5 concise MCQs unless the user requests another count. Each question must have four options (A-D), exactly one correct answer, "
                "and a short explanation after the answer key. Include the publication date/source link for the news fact where possible. "
                "Do not invent a headline or fact absent from the retrieved results. If results are sparse, make fewer questions and explain that limitation. "
                "For exam revision requests, provide a short key-facts recap followed by practice questions.\n"
            )
        if current_affairs_request:
            prompt += (
                "\nCURRENT-AFFAIRS RULES: Use the retrieved news and sources, not model memory. "
                "Start by clarifying the date/recency of the reports when available. Summarize the main developments "
                "in readable bullets. For each item state what happened, who/where, why it matters, and the publication "
                "date when supplied. Separate confirmed facts from allegations, forecasts, and developing reports. "
                "Prefer official statements and multiple reputable outlets when available. Headlines/snippets are not full "
                "verification: say so when details could not be checked. Never invent events or claim this covers every event."
            )
        answer = ""
        research_answer_streamed = False
        stream_final_research = not contact_guard_for_stream and requested_mode not in {"coding", "code"}
        # Sources are known now; send them before the final synthesis and stream the
        # synthesis itself instead of buffering the provider's complete answer.
        yield _source_marker(results)
        if initial_answer_streamed:
            yield "\n\n---\n\n## Verified research update\n\n"
        for provider in configured:
            provider_chunks = []
            emitted_from_provider = False
            try:
                for chunk in _provider_stream(provider, prompt, deep=True, attachments=req.attachments):
                    if chunk:
                        piece = str(chunk)
                        provider_chunks.append(piece)
                        emitted_from_provider = True
                        if stream_final_research:
                            research_answer_streamed = True
                            for visible_fragment in _stream_visible_fragments(piece):
                                yield visible_fragment
                candidate = "".join(provider_chunks).strip()
                if candidate:
                    answer = candidate
                    break
            except Exception as exc:
                print(f"[Indo AI research provider failure] {provider}: {repr(exc)}")
                # Never append another provider's answer into a partial streamed answer.
                if emitted_from_provider:
                    break
                continue
        answer = _guard_unfounded_contact_suggestions(req, _strip_web_decision(answer))
        if answer and _should_review_code(req, answer):
            # Code review requires a complete draft; keep this exceptional path buffered.
            answer = _review_code_answer(req, answer, configured)
        if answer:
            # Keep research Q&A in the dataset for audit/history, but label it non-cacheable
            # so time-sensitive facts are not reused as if they were current.
            if not req.attachments and not req.custom_persona.strip():
                _dataset_save_async(req.message, answer, str(req.mode) + " [research]")
            if not research_answer_streamed:
                yield answer
            return
        if not research_answer_streamed:
            if not initial_answer_streamed:
                yield _source_marker(results)
            if initial_answer_streamed:
                yield "\n\n---\n\n## Research results\n\n"
            yield _web_only_rescue(req, results)
        else:
            yield "\n\nThe research response was interrupted by a temporary provider issue. Please ask Indo to continue."
        return
    if current_affairs_request:
        if initial_answer_streamed:
            yield "\n\n---\n\n**Live verification unavailable:** I couldn't retrieve current headlines, so treat the quick answer above as unverified for today's developments.\n\n"
        query = urllib.parse.quote_plus(_current_affairs_search_query(getattr(req, "message", "")))
        yield _source_marker([
            {"title": "Open Google News live results", "url": "https://news.google.com/search?q=" + query + "&hl=en-IN&gl=IN&ceid=IN%3Aen", "domain": "news.google.com", "engine": "Google News Search"},
            {"title": "Search latest headlines on Bing News", "url": "https://www.bing.com/news/search?q=" + query, "domain": "bing.com", "engine": "Bing News Search"},
        ])
        yield ("I couldn't retrieve live headlines from the news feeds just now, so I won't guess or show outdated news as current. "
               "Please open the live news links above, check that Indo has internet access, and try again.")
        return
    if initial_answer:
        clean_answer = _guard_unfounded_contact_suggestions(req, _strip_web_decision(initial_answer))
        if not req.history and not req.attachments and not req.custom_persona.strip():
            _dataset_save_async(req.message, clean_answer, req.mode)
        if not initial_answer_streamed:
            yield clean_answer
        return
    if failures:
        print("[Indo AI all providers failed] " + " | ".join(failures))
    yield _source_marker([]); yield _local_rescue(req)


