@app.post("/api/library/memory")
async def indo_library_memory_save(req: IndoLibraryMemoryRequest, request: Request):
    root = _indo_library_user_root(request)
    if root is None:
        return JSONResponse({"error": "Sign in to save private project memory."}, status_code=401)
    content = req.content.strip()
    if not content:
        return JSONResponse({"error": "A note cannot be empty."}, status_code=400)
    with _INDO_LIBRARY_LOCK:
        memory_path = root / "memory.json"
        notes = _indo_read_library_memory(memory_path)
        note = {"id": uuid.uuid4().hex, "title": req.title.strip() or "Project note", "content": content, "created_at": _indo_datetime.datetime.now().astimezone().strftime("%Y-%m-%d %H:%M %Z")}
        notes.insert(0, note)
        _indo_write_library_memory(notes[:300], memory_path)
    return {"ok": True, "note": note}

@app.delete("/api/library/memory/{note_id}")
async def indo_library_memory_delete(note_id: str, request: Request):
    root = _indo_library_user_root(request)
    if root is None:
        return JSONResponse({"error": "Sign in to manage private project memory."}, status_code=401)
    with _INDO_LIBRARY_LOCK:
        memory_path = root / "memory.json"
        notes = _indo_read_library_memory(memory_path)
        updated = [n for n in notes if str(n.get("id")) != note_id]
        if len(updated) == len(notes):
            return JSONResponse({"error": "Note not found."}, status_code=404)
        _indo_write_library_memory(updated, memory_path)
    return {"ok": True}

@app.get("/api/indo-lab/diagnostics")
async def indo_lab_diagnostics():
    info = {"ok": True, "app": APP_NAME, "version": APP_VERSION, "python": __import__("sys").version.split()[0], "platform": __import__("platform").platform(), "api_keys_configured": {"gemini": bool(API_KEYS), "sarvam": bool(os.getenv("SARVAM_API_KEY")), "elevenlabs": bool(os.getenv("ELEVENLABS_API_KEY"))}, "data_directory_writable": os.access(str(INDO_DATA_DIR), os.W_OK), "upload_directory_writable": os.access(str(UPLOAD_DIR), os.W_OK), "performance": {"requests": REQUEST_STATS.get("requests", 0), "completed": REQUEST_STATS.get("completed", 0), "errors": REQUEST_STATS.get("errors", 0), "uptime_seconds": round(max(0, time.time() - SERVER_STARTED_AT), 1)}, "gpu": {"torch_available": False, "cuda_available": False, "note": "Optional GPU libraries are checked only if already installed; detection does not activate an on-device model."}}
    try:
        import psutil
        process = psutil.Process()
        info["process"] = {"rss_mb": round(process.memory_info().rss / 1024**2, 1), "cpu_percent_sample": process.cpu_percent(interval=0.05), "threads": process.num_threads()}
    except Exception:
        info["process"] = {"note": "Install psutil for detailed process metrics."}
    try:
        import torch
        info["gpu"]["torch_available"] = True
        info["gpu"]["cuda_available"] = bool(torch.cuda.is_available())
        if torch.cuda.is_available(): info["gpu"]["device"] = torch.cuda.get_device_name(0)
    except Exception:
        pass
    return info

