@app.get("/api/indo-hyperlocal/profile")
async def indo_hyperlocal_profile_get(request: Request):
    user = _indo_current_user(request)
    if not user: return JSONResponse({"error": "Sign in required."}, status_code=401)
    if not INDO_HYPERLOCAL: return JSONResponse({"error": "Hyper-local preferences unavailable."}, status_code=503)
    identity = str(user.get("user_key") or (user.get("provider", "") + ":" + user.get("email", "")))
    # Restore encrypted cloud preferences before returning the local cache.
    if INDO_DLM and _indo_cloud_ready():
        try:
            _uh = INDO_DLM.user_hash(identity)
            _row = _indo_cloud_get_user_state(_uh, "hyperlocal_profile_v1")
            _payload = _row.get("payload", {}) if isinstance(_row, dict) else {}
            _enc = _payload.get("encrypted_snapshot", "") if isinstance(_payload, dict) else ""
            if _enc:
                _profile = json.loads(INDO_DLM.cipher.decrypt(_enc.encode("ascii")).decode("utf-8"))
                INDO_HYPERLOCAL.update(identity, _profile)
        except Exception as _hyperlocal_restore_error:
            print("[Indo hyper-local cloud restore warning]", type(_hyperlocal_restore_error).__name__)
    return JSONResponse(INDO_HYPERLOCAL.get(identity), headers={"Cache-Control": "private, no-store"})

@app.put("/api/indo-hyperlocal/profile")
async def indo_hyperlocal_profile_update(req: IndoHyperLocalProfileRequest, request: Request):
    user = _indo_current_user(request)
    if not user: return JSONResponse({"error": "Sign in required."}, status_code=401)
    if not INDO_HYPERLOCAL: return JSONResponse({"error": "Hyper-local preferences unavailable."}, status_code=503)
    identity = str(user.get("user_key") or (user.get("provider", "") + ":" + user.get("email", "")))
    try:
        result = INDO_HYPERLOCAL.update(identity, req.model_dump())
        cloud_synced = False
        if INDO_DLM and _indo_cloud_ready():
            try:
                _uh = INDO_DLM.user_hash(identity)
                _enc = INDO_DLM.cipher.encrypt(json.dumps(result, separators=(",", ":")).encode("utf-8")).decode("ascii")
                _indo_cloud_put_user_state(_uh, "hyperlocal_profile_v1", {"version": 1, "encrypted_snapshot": _enc, "updated_at": int(time.time())})
                cloud_synced = True
            except Exception as _hyperlocal_sync_error:
                print("[Indo hyper-local cloud sync warning]", type(_hyperlocal_sync_error).__name__)
        return JSONResponse({"ok": True, "profile": result, "cloud_synced": cloud_synced}, headers={"Cache-Control": "private, no-store"})
    except ValueError as exc:
        return JSONResponse({"error": str(exc)}, status_code=400)

