@app.post("/api/indo-intelligence/plan")
async def indo_intelligence_plan(request: Request):
    """Expose the local task plan for Indo Lab diagnostics; no provider call is made."""
    try:
        payload = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Send a JSON object containing message and optional mode."}, status_code=400)
    if not isinstance(payload, dict):
        return JSONResponse({"ok": False, "error": "A JSON object is required."}, status_code=400)
    message = str(payload.get("message", ""))[:12000]
    mode = str(payload.get("mode", "New Chat"))[:80]
    try:
        attachment_count = min(10, max(0, int(payload.get("attachment_count", 0))))
        history_count = min(500, max(0, int(payload.get("history_count", 0))))
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "attachment_count and history_count must be integers."}, status_code=400)
    plan = plan_intelligence(message, mode, attachment_count, history_count)
    return {"ok": True, "version": APP_VERSION, "plan": plan,
            "guidance": intelligence_guidance(plan),
            "note": "Local heuristic only. It does not execute tools, call a model, or score factual accuracy."}

