@app.post("/api/indo-vishnu/benchmarks/run")
async def indo_vishnu_benchmarks_run(request: Request):
    """Explicit, signed-in, bounded local benchmark; never spends cloud API credits."""
    user = _indo_current_user(request)
    if not user:
        return JSONResponse({"ok": False, "error": "Sign in before running a benchmark."}, status_code=401,
                            headers={"Cache-Control": "no-store"})
    try:
        payload = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Send a JSON object with limit and optional categories."}, status_code=400)
    if not isinstance(payload, dict):
        return JSONResponse({"ok": False, "error": "A JSON object is required."}, status_code=400)
    try:
        limit = int(payload.get("limit", 10))
        offset = int(payload.get("offset", 0))
        timeout = float(payload.get("timeout_seconds", min(OLLAMA_PROVIDER_TIMEOUT, 120.0)))
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "limit and timeout_seconds must be numeric."}, status_code=400)
    if limit < 1 or limit > 40 or offset < 0 or offset > 139:
        return JSONResponse({"ok": False, "error": "Each run is limited to 1–40 cases; offset must be between 0 and 139."}, status_code=400)
    categories = payload.get("categories", [])
    if not isinstance(categories, list) or len(categories) > 6 or not all(isinstance(x, str) for x in categories):
        return JSONResponse({"ok": False, "error": "categories must be an array of up to six category names."}, status_code=400)
    try:
        result = await asyncio.to_thread(run_local_intelligence_benchmark,
            base_url=OLLAMA_BASE_URL, model=OLLAMA_MODEL, limit=limit, offset=offset,
            categories=categories or None, timeout=timeout)
    except ValueError as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    except Exception as exc:
        print("[Indo benchmark error]", type(exc).__name__, str(exc)[:240])
        return JSONResponse({"ok": False, "error": "The local benchmark could not start. Check Ollama and its configured model."}, status_code=503)
    return JSONResponse({"ok": True, "version": APP_VERSION, "benchmark": result},
                        headers={"Cache-Control": "no-store"})


