@app.delete("/api/indo-vishnu/knowledge/delete")
async def indo_vishnu_knowledge_delete(request: Request, topic: str = ""):
    user = _indo_current_user(request)
    if not user:
        return JSONResponse({"ok": False, "error": "Sign in to delete private knowledge."}, status_code=401)
    if not topic.strip():
        return JSONResponse({"ok": False, "error": "A topic is required."}, status_code=400)
    deleted = VISHNU_KNOWLEDGE_STORE.delete_topic(str(user.get("user_key") or user.get("email") or ""), topic)
    return JSONResponse({"ok": True, "deleted_versions": deleted}, headers={"Cache-Control": "no-store"})

