# ============================================================
# INDO AI v8.77 — MODULAR CORE EXPANSION ROUTES
# The helpers live in indo_core/ so each component can be tested independently.
# ============================================================
try:
    from indo_core.config import load_settings as _indo_exp_load_settings, validate_settings as _indo_exp_validate_settings
    from indo_core.diagnostics import run_diagnostics as _indo_exp_run_diagnostics
    from indo_core.input_guard import InputGuard as _IndoInputGuard
    from indo_core.prompts import PromptLibrary as _IndoPromptLibrary
    _indo_exp_prompt_library = _IndoPromptLibrary()
    _indo_exp_input_guard = _IndoInputGuard()

    @app.get("/api/expansion/diagnostics")
    async def indo_expansion_diagnostics():
        _settings = _indo_exp_load_settings()
        if not _settings.diagnostics_enabled:
            return JSONResponse({"enabled": False, "message": "Diagnostics are disabled by configuration."}, status_code=404)
        _report = _indo_exp_run_diagnostics(Path(__file__).resolve().parent)
        return {"enabled": True, "report": _report.to_dict(), "configuration_warnings": _indo_exp_validate_settings(_settings)}

    @app.get("/api/expansion/prompt-presets")
    async def indo_expansion_prompt_presets():
        return {"presets": _indo_exp_prompt_library.list()}

    @app.post("/api/expansion/render-prompt")
    async def indo_expansion_render_prompt(request: Request):
        try:
            _payload = await request.json()
        except Exception:
            return JSONResponse({"error": "Expected a JSON request body."}, status_code=400)
        if not isinstance(_payload, dict):
            return JSONResponse({"error": "Expected a JSON object."}, status_code=400)
        _name = _payload.get("name", "")
        _values = _payload.get("values", {})
        if not isinstance(_name, str) or not isinstance(_values, dict):
            return JSONResponse({"error": "name must be text and values must be an object."}, status_code=400)
        try:
            _rendered = _indo_exp_prompt_library.render(_name, _values)
        except KeyError:
            return JSONResponse({"error": "Unknown prompt preset."}, status_code=404)
        except (TypeError, ValueError):
            return JSONResponse({"error": "Prompt values are incomplete or invalid."}, status_code=400)
        return {"name": _name, "prompt": _rendered}

    @app.post("/api/expansion/validate-input")
    async def indo_expansion_validate_input(request: Request):
        try:
            _payload = await request.json()
        except Exception:
            return JSONResponse({"error": "Expected a JSON request body."}, status_code=400)
        if not isinstance(_payload, dict) or not isinstance(_payload.get("text"), str):
            return JSONResponse({"error": "text must be a string."}, status_code=400)
        _result = _indo_exp_input_guard.check(_payload["text"])
        return {"accepted": _result.accepted, "text": _result.text if _result.accepted else "",
                "reasons": list(_result.reasons), "normalized_length": _result.normalized_length}
except ImportError as _indo_expansion_import_error:
    # The core app remains bootable if the optional package is not deployed beside it.
    print(f"[Indo expansion] Optional core modules unavailable: {type(_indo_expansion_import_error).__name__}")


